// Tata bahasa + terjemahan Indonesia (otomatis via Google Translate).
export default [{"pattern":"A とか B とか","meaning":"Used to express multiple examples or possibilities; 'such as', 'like', 'for example'.","meaningId":"Digunakan untuk menyatakan berbagai contoh atau kemungkinan; 'seperti', 'seperti', 'misalnya'.","formation":"Noun + とか + Noun + とか","formationId":"Kata Benda + とか + Kata Benda + とか","examples":[{"jp":"週末は映画とか買い物とか楽しいことをしたいです。","romaji":"Shuumatsu wa eiga toka kaimono toka tanoshii koto o shitai desu.","en":"I want to do fun things like watching movies and shopping on the weekend.","id":"Saya ingin melakukan hal-hal menyenangkan seperti menonton film dan berbelanja di akhir pekan."},{"jp":"彼女は英語とかフランス語とかいろいろな言葉を話せます。","romaji":"Kanojo wa eigo toka furansugo toka iroirona kotoba o hanasemasu.","en":"She can speak various languages, like English and French.","id":"Dia bisa berbicara berbagai bahasa, seperti Inggris dan Prancis."},{"jp":"この店は寿司とか刺身とか日本料理を提供しています。","romaji":"Kono mise wa sushi toka sashimi toka nihon ryouri o teikyou shiteimasu.","en":"This restaurant offers Japanese dishes such as sushi and sashimi.","id":"Restoran ini menawarkan masakan Jepang seperti sushi dan sashimi."},{"jp":"$1BOXとか$5BOXとか、異なる価格のランチBOXがあります。","romaji":"Ichi-doru BOX toka go-doru BOX toka, kotonaru kakaku no ranchi BOX ga arimasu.","en":"There are lunch boxes with different prices, like $1 boxes and $5 boxes.","id":"Ada kotak makan siang dengan harga berbeda, seperti $1 kotak dan $5 kotak."}]},{"pattern":"A は B ほど～ありません","meaning":"Express that A is not as much as B; 'not as... as', 'not... to the extent of'.","meaningId":"Nyatakan bahwa A tidak sebanyak B; 'tidak sebagai... sebagai', 'tidak... sebatas'.","formation":"A は B ほど Verb/adjective ありません","formationId":"A は B ほど Kata kerja/kata sifat ありません","examples":[{"jp":"今日は昨日ほど寒くありません。","romaji":"Kyou wa kinou hodo samuku arimasen.","en":"Today is not as cold as yesterday.","id":"Hari ini tidak sedingin kemarin."},{"jp":"彼は私ほど上手に英語を話せません。","romaji":"Kare wa watashi hodo jouzu ni eigo o hanasemasen.","en":"He cannot speak English as well as I can.","id":"Dia tidak bisa berbahasa Inggris sebaik saya."},{"jp":"このレストランはあのレストランほど高くありません。","romaji":"Kono resutoran wa ano resutoran hodo takaku arimasen.","en":"This restaurant is not as expensive as that restaurant.","id":"Restoran ini tidak semahal restoran itu."},{"jp":"彼女は彼ほど忙しくありません。","romaji":"Kanojo wa kare hodo isogashiku arimasen.","en":"She is not as busy as him.","id":"Dia tidak sesibuk dia."}]},{"pattern":"A は B ほど～ない","meaning":"Expressing that A is not as ~ as B; 'not as...as'","meaningId":"Menyatakan bahwa A tidak ~ seperti B; 'tidak sebagai... sebagai'","formation":"A は B ほど + い-Adjective stem (without い) + くない, な-Adjective + じゃない, Verb-negative potential form","formationId":"A は B ほど + い-Kata sifat batang (tanpa い) + くない, な-Kata Sifat + じゃない, Bentuk potensial kata kerja-negatif","examples":[{"jp":"山田さんは鈴木さんほど背が高くない。","romaji":"Yamada-san wa Suzuki-san hodo se ga takakunai.","en":"Yamada is not as tall as Suzuki.","id":"Yamada tidak setinggi Suzuki."},{"jp":"このリンゴはあのリンゴほど甘くない。","romaji":"Kono ringo wa ano ringo hodo amakunai.","en":"This apple is not as sweet as that apple.","id":"Apel ini tidak semanis apel itu."},{"jp":"彼は私ほど勉強ができない。","romaji":"Kare wa watashi hodo benkyou ga dekinai.","en":"He can't study as well as I can.","id":"Dia tidak bisa belajar sebaik saya."},{"jp":"このレストランはあのレストランほど静かじゃない。","romaji":"Kono resutoran wa ano resutoran hodo shizuka janai.","en":"This restaurant is not as quiet as that restaurant.","id":"Restoran ini tidak senyap restoran itu."}]},{"pattern":"A より B のほうが〜 (A yori B no hou ga 〜)","meaning":"Comparing two things; 'B is more ~ than A'.","meaningId":"Membandingkan dua hal; 'B lebih ~ dari A'.","formation":"A + より + B + のほうが + Adjective/Verb","formationId":"A + より + B + のほうが + Kata Sifat/Kata Kerja","examples":[{"jp":"田中さんより鈴木さんのほうが背が高いです。","romaji":"Tanaka-san yori Suzuki-san no hou ga se ga takai desu.","en":"Suzuki is taller than Tanaka.","id":"Suzuki lebih tinggi dari Tanaka."},{"jp":"リンゴよりバナナのほうが甘いです。","romaji":"Ringo yori banana no hou ga amai desu.","en":"Bananas are sweeter than apples.","id":"Pisang lebih manis dari apel."},{"jp":"冬より夏のほうが暑いです。","romaji":"Fuyu yori natsu no hou ga atsui desu.","en":"Summer is hotter than winter.","id":"Musim panas lebih panas daripada musim dingin."},{"jp":"東京より京都のほうが歴史があると思います。","romaji":"Toukyou yori Kyouto no hou ga rekishi ga aru to omoimasu.","en":"I think Kyoto has more history than Tokyo.","id":"Saya pikir Kyoto memiliki lebih banyak sejarah daripada Tokyo."}]},{"pattern":"い-Adjective く する/なる (i-Adjective kusuru/naru)","meaning":"Express a change happening or making something change.","meaningId":"Menyatakan perubahan yang terjadi atau membuat sesuatu berubah.","formation":"い-Adjective (remove い) + く + する/なる","formationId":"い-Kata sifat (hapus い) + く + する/なる","examples":[{"jp":"部屋を明るくします。","romaji":"Heya o akaruku shimasu.","en":"I will make the room brighter.","id":"Saya akan membuat ruangan lebih terang."},{"jp":"彼の顔は赤くなりました。","romaji":"Kare no kao wa akaku narimashita.","en":"His face turned red.","id":"Wajahnya memerah."},{"jp":"この料理を辛くしてください。","romaji":"Kono ryouri o karaku shite kudasai.","en":"Please make this dish spicy.","id":"Tolong buat hidangan ini pedas."},{"jp":"雨が降ると、道が滑りやすくなります。","romaji":"Ame ga furu to, michi ga suberiyasuku narimasu.","en":"When it rains, the road becomes slippery.","id":"Saat hujan, jalanan menjadi licin."}]},{"pattern":"な-adjective に する/なる","meaning":"Used to indicate change or decision; 'to become' or 'to make' with na-adjectives.","meaningId":"Digunakan untuk menunjukkan perubahan atau keputusan; 'menjadi' atau 'membuat' dengan kata sifat na.","formation":"な-Adjective + に + する/なる","formationId":"な-Kata sifat + に + する/なる","examples":[{"jp":"部屋をきれいにする。","romaji":"Heya o kirei ni suru.","en":"To make the room clean.","id":"Untuk membuat ruangan menjadi bersih."},{"jp":"彼は元気になりました。","romaji":"Kare wa genki ni narimashita.","en":"He became energetic.","id":"Dia menjadi energik."},{"jp":"毎日静かにすることが大切です。","romaji":"Mainichi shizuka ni suru koto ga taisetsu desu.","en":"It is important to make it quiet every day.","id":"Penting untuk menenangkannya setiap hari."},{"jp":"日本語の勉強が楽しくなるように努力します。","romaji":"Nihongo no benkyou ga tanoshiku naru you ni doryoku shimasu.","en":"I will try to make studying Japanese become enjoyable.","id":"Saya akan mencoba membuat belajar bahasa Jepang menjadi menyenangkan."}]},{"pattern":"Noun しか～ない","meaning":"Expresses 'only', 'nothing but', or 'no other'.","meaningId":"Menyatakan 'hanya', 'tidak lain', atau 'tidak ada yang lain'.","formation":"Noun + しか + Negative Verb","formationId":"Kata Benda + しか + Kata Kerja Negatif","examples":[{"jp":"私はリンゴしか食べない。","romaji":"Watashi wa ringo shika tabenai.","en":"I eat only apples.","id":"Saya hanya makan apel."},{"jp":"電車で行くしかないです。","romaji":"Densha de iku shika nai desu.","en":"There is no other way but to go by train.","id":"Tidak ada jalan lain selain naik kereta api."},{"jp":"彼は一冊の本しか持っていない。","romaji":"Kare wa isatsu no hon shika motte inai.","en":"He has only one book.","id":"Dia hanya punya satu buku."},{"jp":"この店にはビールしかない。","romaji":"Kono mise ni wa biiru shika nai.","en":"There is nothing but beer in this store.","id":"Tidak ada apa pun selain bir di toko ini."}]},{"pattern":"Noun に する","meaning":"Used to indicate a choice or decision, 'to decide on' or 'to choose'.","meaningId":"Digunakan untuk menunjukkan pilihan atau keputusan, 'memutuskan' atau 'memilih'.","formation":"Noun + に + する","formationId":"Kata benda + に + する","examples":[{"jp":"メニューからピザにしました。","romaji":"Menyu kara piza ni shimashita.","en":"I decided on pizza from the menu.","id":"Saya memutuskan pizza dari menu."},{"jp":"誕生日プレゼントに時計にするつもりです。","romaji":"Tanjoubi purezento ni tokei ni suru tsumori desu.","en":"I plan to choose a watch as a birthday present.","id":"Saya berencana memilih jam tangan sebagai hadiah ulang tahun."},{"jp":"今日の午後は買い物にすることにしました。","romaji":"Kyou no gogo wa kaimono ni suru koto ni shimashita.","en":"I decided to go shopping this afternoon.","id":"Aku memutuskan untuk pergi berbelanja sore ini."},{"jp":"海外旅行の目的地として、日本にする。","romaji":"Kaigai ryokou no mokutekichi toshite, Nihon ni suru.","en":"I will choose Japan as the destination for my overseas trip.","id":"Saya akan memilih Jepang sebagai tujuan perjalanan saya ke luar negeri."}]},{"pattern":"Noun に なる","meaning":"To become; to change into; to turn into.","meaningId":"Menjadi; untuk berubah menjadi; untuk berubah menjadi.","formation":"Noun + に + なる","formationId":"Kata benda + に + なる","examples":[{"jp":"彼は医者になりました。","romaji":"Kare wa isha ni narimashita.","en":"He became a doctor.","id":"Dia menjadi seorang dokter."},{"jp":"子供の頃、私は先生になりたかったです。","romaji":"Kodomo no koro, watashi wa sensei ni naritakatta desu.","en":"When I was a child, I wanted to become a teacher.","id":"Ketika saya masih kecil, saya ingin menjadi seorang guru."},{"jp":"彼女は緊張して顔が赤くなりました。","romaji":"Kanojo wa kinchou shite kao ga akaku narimashita.","en":"She got nervous, and her face turned red.","id":"Dia menjadi gugup, dan wajahnya memerah."},{"jp":"春になると桜が咲きます。","romaji":"Haru ni naru to sakura ga sakimasu.","en":"When it becomes spring, cherry blossoms bloom.","id":"Saat memasuki musim semi, bunga sakura bermekaran."}]},{"pattern":"のために","meaning":"Used to express purpose or reason; 'for', 'for the sake of', 'in order to'.","meaningId":"Digunakan untuk menyatakan tujuan atau alasan; 'untuk', 'demi', 'untuk'.","formation":"Noun + のために","formationId":"Kata benda + のために","examples":[{"jp":"勉強のために、図書館で静かな場所を探しています。","romaji":"Benkyou no tame ni, toshokan de shizukana basho o sagashiteimasu.","en":"In order to study, I am looking for a quiet place in the library.","id":"Untuk belajar, saya mencari tempat yang tenang di perpustakaan."},{"jp":"彼は家族のために、一生懸命働いています。","romaji":"Kare wa kazoku no tame ni, isshoukenmei hataraiteimasu.","en":"He works hard for the sake of his family.","id":"Dia bekerja keras demi keluarganya."},{"jp":"健康のために、毎日運動をしています。","romaji":"Kenkou no tame ni, mainichi undou o shiteimasu.","en":"I exercise every day for the sake of my health.","id":"Saya berolahraga setiap hari demi kesehatan saya."},{"jp":"世界平和のために、みんなで協力しましょう。","romaji":"Sekai heiwa no tame ni, minna de kyouryoku shimashou.","en":"Let's all cooperate for the sake of world peace.","id":"Mari kita semua bekerja sama demi perdamaian dunia."}]},{"pattern":"Noun の 間に (〜no aida ni)","meaning":"Expresses 'while' or 'during' a specific period or time.","meaningId":"Menyatakan 'sementara' atau 'selama' periode atau waktu tertentu.","formation":"Noun + の間に","formationId":"Kata benda + の間に","examples":[{"jp":"昼休みの間に銀行に行きます。","romaji":"Hiruyasumi no aida ni ginkou ni ikimasu.","en":"I will go to the bank during lunch break.","id":"Saya akan pergi ke bank saat istirahat makan siang."},{"jp":"夏休みの間に海外旅行に行く予定です。","romaji":"Natsuyasumi no aida ni kaigai ryokou ni iku yotei desu.","en":"I plan to go on an overseas trip during the summer vacation.","id":"Saya berencana untuk melakukan perjalanan ke luar negeri selama liburan musim panas."},{"jp":"子供たちが学校の間に買い物に行きました。","romaji":"Kodomo-tachi ga gakkou no aida ni kaimono ni ikimashita.","en":"I went shopping while the kids were at school.","id":"Saya pergi berbelanja saat anak-anak berada di sekolah."},{"jp":"母の日にお母さんにプレゼントを送りました。","romaji":"Haha no hi ni okaasan ni purezento o okurimashita.","en":"I sent a gift to my mother on Mother’s Day.","id":"Saya mengirim hadiah kepada ibu saya di Hari Ibu."}]},{"pattern":"Noun ばかり (〜bakari)","meaning":"Expresses 'only', 'nothing but', 'always', or 'just'.","meaningId":"Menyatakan 'hanya', 'tidak lain', 'selalu', atau 'hanya'.","formation":"Noun + ばかり, Verb-casual + ばかり, い-Adjective + ばかり, な-Adjective + だ ばかり","formationId":"Kata benda + ばかり, Kata Kerja-kasual + ばかり, い-Kata Sifat + ばかり, な-Kata Sifat + だ ばかり","examples":[{"jp":"彼はお金の話ばかりする。","romaji":"Kare wa okane no hanashi bakari suru.","en":"He talks about nothing but money.","id":"Dia hanya berbicara tentang uang."},{"jp":"彼女は勉強ばかりしている。","romaji":"Kanojo wa benkyou bakari shiteiru.","en":"She is always studying.","id":"Dia selalu belajar."},{"jp":"デパートには高い商品ばかりだ。","romaji":"Depaato ni wa takai shouhin bakari da.","en":"There are only expensive items in the department store.","id":"Hanya ada barang-barang mahal di department store."},{"jp":"この部屋は狭いばかりだ。","romaji":"Kono heya wa semai bakari da.","en":"This room is nothing but small.","id":"Ruangan ini hanyalah kecil."}]},{"pattern":"Noun を あげる","meaning":"To give something to someone; 'give', 'offer', 'present'.","meaningId":"Untuk memberikan sesuatu kepada seseorang; 'memberi', 'menawarkan', 'menghadiahkan'.","formation":"Noun + を + あげる","formationId":"Kata benda + を + あげる","examples":[{"jp":"プレゼントをあげる。","romaji":"Purezento wo ageru.","en":"I give a present.","id":"Saya memberikan hadiah."},{"jp":"友達に花をあげた。","romaji":"Tomodachi ni hana wo ageta.","en":"I gave flowers to my friend.","id":"Saya memberikan bunga kepada teman saya."},{"jp":"父に時計をあげます。","romaji":"Chichi ni tokei wo agemasu.","en":"I will give a watch to my father.","id":"Saya akan memberikan jam tangan kepada ayah saya."},{"jp":"彼女に手紙をあげたい。","romaji":"Kanojo ni tegami wo agetai.","en":"I want to give her a letter.","id":"Saya ingin memberinya surat."}]},{"pattern":"Nounをいただく","meaning":"To receive or accept something politely; 'to receive', 'to get', 'to accept'.","meaningId":"Untuk menerima atau menerima sesuatu dengan sopan; 'menerima', 'mendapatkan', 'menerima'.","formation":"Noun + を + いただく","formationId":"Kata Benda + を + いただく","examples":[{"jp":"プレゼントをいただきありがとうございます。","romaji":"Purezento wo itadaki arigatou gozaimasu.","en":"Thank you for the gift that I received.","id":"Terima kasih atas hadiah yang saya terima."},{"jp":"先生からアドバイスをいただきました。","romaji":"Sensei kara adobaisu wo itadakimashita.","en":"I received advice from my teacher.","id":"Aku mendapat nasehat dari guruku."},{"jp":"このコーヒーをいただいていいですか？","romaji":"Kono koohii wo itadaite ii desu ka?","en":"May I have this coffee?","id":"Bolehkah saya minta kopi ini?"},{"jp":"会社の上司に昇進のお知らせをいただきました。","romaji":"Kaisha no joushi ni shoushin no oshirase wo itadakimashita.","en":"I received a promotion notification from my boss at the company.","id":"Saya menerima pemberitahuan promosi dari atasan saya di perusahaan."}]},{"pattern":"Nounをくださる","meaning":"Used to express someone doing something as a favor or for the benefit of the speaker.","meaningId":"Digunakan untuk menyatakan seseorang melakukan sesuatu untuk kepentingan atau kepentingan pembicara.","formation":"Noun + を + くださる","formationId":"Kata Benda + を + くださる","examples":[{"jp":"先生が資料をくださった。","romaji":"Sensei ga shiryou wo kudasatta.","en":"The teacher gave me the materials.","id":"Guru memberi saya materi."},{"jp":"お母さんがおやつをくださる。","romaji":"Okaasan ga oyatsu wo kudasaru.","en":"My mother gives me snacks.","id":"Ibuku memberiku makanan ringan."},{"jp":"上司がアドバイスをくださいました。","romaji":"Joushi ga adobaisu wo kudasaimashita.","en":"My boss gave me advice.","id":"Bos saya memberi saya nasihat."},{"jp":"友達がプレゼントをくださった。","romaji":"Tomodachi ga purezento wo kudasatta.","en":"My friend gave me a present.","id":"Temanku memberiku hadiah."}]},{"pattern":"Noun を くれる","meaning":"Expresses that someone gives a thing to the speaker or someone close to the speaker.","meaningId":"Menyatakan bahwa seseorang memberikan sesuatu kepada pembicara atau seseorang yang dekat dengan pembicara.","formation":"Giver + が + Receiver + に + Noun + を + くれる","formationId":"Pemberi + が + Penerima + に + Kata Benda + を + くれる","examples":[{"jp":"友達が私にプレゼントをくれました。","romaji":"Tomodachi ga watashi ni purezento wo kuremashita.","en":"My friend gave me a present.","id":"Temanku memberiku hadiah."},{"jp":"彼が私に花をくれた。","romaji":"Kare ga watashi ni hana wo kureta.","en":"He gave me flowers.","id":"Dia memberiku bunga."},{"jp":"先生が私に本をくれました。","romaji":"Sensei ga watashi ni hon wo kuremashita.","en":"The teacher gave me a book.","id":"Guru memberi saya sebuah buku."},{"jp":"お母さんが弟にお菓子をくれました。","romaji":"Okaasan ga otouto ni okashi wo kuremashita.","en":"Mom gave my little brother some sweets.","id":"Ibu memberi adikku permen."}]},{"pattern":"Noun を さしあげる","meaning":"A polite way of expressing to give something.","meaningId":"Cara yang sopan untuk menyatakan memberi sesuatu.","formation":"Noun + を + さしあげる","formationId":"Kata Benda + を + さしあげる","examples":[{"jp":"先生に本をさしあげます。","romaji":"Sensei ni hon wo sashiagemasu.","en":"I will give a book to the teacher.","id":"Saya akan memberikan buku kepada guru."},{"jp":"お母さんに花をさしあげたいです。","romaji":"Okaasan ni hana wo sashiagetai desu.","en":"I want to give flowers to my mother.","id":"Saya ingin memberikan bunga kepada ibu saya."},{"jp":"お客様にお茶をさしあげましょう。","romaji":"Okyakusama ni ocha wo sashiagemashou.","en":"Let's offer tea to the guest.","id":"Mari kita tawarkan teh kepada tamu."},{"jp":"先輩にプレゼントをさしあげたら、喜んでいました。","romaji":"Senpai ni purezento wo sashiagetara, yorokonde imashita.","en":"When I gave a present to my senior, they were delighted.","id":"Ketika saya memberikan hadiah kepada senior saya, mereka sangat senang."}]},{"pattern":"Noun もらう","meaning":"To receive or get something from someone; 'to receive', 'to get'.","meaningId":"Untuk menerima atau mendapatkan sesuatu dari seseorang; 'menerima', 'mendapatkan'.","formation":"Noun + を + もらう","formationId":"Kata Benda + を + もらう","examples":[{"jp":"友達からプレゼントをもらいました。","romaji":"Tomodachi kara purezento wo moraimashita.","en":"I received a gift from my friend.","id":"Saya menerima hadiah dari teman saya."},{"jp":"先生にアドバイスをもらいました。","romaji":"Sensei ni adobaisu wo moraimashita.","en":"I got advice from my teacher.","id":"Aku mendapat nasehat dari guruku."},{"jp":"お父さんからお小遣いをもらう。","romaji":"Otousan kara okozukai wo morau.","en":"To receive an allowance from one's father.","id":"Untuk menerima tunjangan dari ayah seseorang."},{"jp":"彼女に手紙をもらった。","romaji":"Kanojo ni tegami wo moratta.","en":"I got a letter from her.","id":"Saya mendapat surat darinya."}]},{"pattern":"Noun + 中 (Noun + ちゅう)","meaning":"Express 'in the middle of', 'during', or 'in the process of'.","meaningId":"Ekspresikan 'di tengah', 'selama', atau 'dalam proses'.","formation":"Noun + 中 (ちゅう)","formationId":"Kata benda + 中 (ちゅう)","examples":[{"jp":"彼は仕事中です。","romaji":"Kare wa shigotochuu desu.","en":"He is in the middle of work.","id":"Dia sedang bekerja."},{"jp":"試験中、携帯電話を使ってはいけません。","romaji":"Shiken chuu, keitai denwa wo tsukatte wa ikemasen.","en":"During the exam, you must not use your mobile phone.","id":"Selama ujian, Anda tidak boleh menggunakan ponsel Anda."},{"jp":"映画を観ている最中に、彼は泣き始めました。","romaji":"Eiga o mite iru saichuu ni, kare wa naki hajimemashita.","en":"In the middle of watching the movie, he started to cry.","id":"Di tengah menonton film, dia mulai menangis."},{"jp":"彼女は今勉強中です。","romaji":"Kanojo wa ima benkyouchuu desu.","en":"She is currently studying.","id":"Dia sedang belajar."}]},{"pattern":"Verb させられる (Verb-saserareru)","meaning":"Express the passive causative form; 'to be made to', 'to be forced to'.","meaningId":"Ekspresikan bentuk kausatif pasif; 'dipaksa', 'dipaksa'.","formation":"Group 1 Verb: Replace ～う with ～わせられる, Group 2 Verb: Replace ～る with ～させられる, Group 3 Verb: する → させられる, くる → こさせられる","formationId":"Kata Kerja Kelompok 1: Ganti ～う dengan ～わせられる, Kata Kerja Kelompok 2: Ganti ～る dengan ～させられる, Kata Kerja Kelompok 3: する → させられる, くる →こさせられる","examples":[{"jp":"子供たちは先生に宿題をやらせられました。","romaji":"Kodomo-tachi wa sensei ni shukudai wo yaraseraremashita.","en":"The children were made to do their homework by the teacher.","id":"Anak-anak disuruh mengerjakan pekerjaan rumahnya oleh guru."},{"jp":"彼は会社にもっと働かせられた。","romaji":"Kare wa kaisha ni motto hatarakaserareta.","en":"He was forced to work more by the company.","id":"Dia dipaksa bekerja lebih banyak oleh perusahaan."},{"jp":"私は友達にその機密を話させられました。","romaji":"Watashi wa tomodachi ni sono kimitsu o hanasaseraremashita.","en":"I was made to reveal that secret by my friend.","id":"Saya dibuat untuk mengungkapkan rahasia itu oleh teman saya."},{"jp":"怪我をした選手は、コーチに休ませられました。","romaji":"Kega wo shita senshu wa, kouchi ni yasumaseraremashita.","en":"The injured player was forced to rest by the coach.","id":"Pemain yang cedera itu terpaksa diistirahatkan oleh pelatih."}]},{"pattern":"Verb させる (Verb-saseru)","meaning":"Expresses 'to make someone do something', 'to let someone do something', or 'to cause someone to do something'.","meaningId":"Menyatakan 'membuat seseorang melakukan sesuatu', 'membiarkan seseorang melakukan sesuatu', atau 'menyebabkan seseorang melakukan sesuatu'.","formation":"Group 1 Verbs: Change the last hiragana to ～せる, Group 2 Verbs: Remove ～る and add ～させる, Group 3 Verbs: する → させる, くる → こさせる","formationId":"Kata Kerja Grup 1: Ubah hiragana terakhir menjadi ～せる, Kata Kerja Grup 2: Hapus ～る dan tambahkan ～させる, Kata Kerja Grup 3: する → させる, くる → こさせる","examples":[{"jp":"先生が生徒に宿題をさせました。","romaji":"Sensei ga seito ni shukudai o sasemashita.","en":"The teacher made the students do homework.","id":"Guru menyuruh siswa mengerjakan pekerjaan rumah."},{"jp":"母が私に部屋を掃除させました。","romaji":"Haha ga watashi ni heya o souji sasemashita.","en":"My mother made me clean my room.","id":"Ibuku menyuruhku membersihkan kamarku."},{"jp":"彼女にピアノを弾かせてあげました。","romaji":"Kanojo ni piano o hikasete agemashita.","en":"I let her play the piano.","id":"Aku membiarkannya bermain piano."},{"jp":"上司は彼にそのプログラムを作らせました。","romaji":"Joushi wa kare ni sono puroguramu o tsukurasemashita.","en":"The boss made him create the program.","id":"Bos menyuruhnya membuat program."}]},{"pattern":"Verb た ことがある","meaning":"Expresses the experience of having done something in the past.","meaningId":"Mengungkapkan pengalaman telah melakukan sesuatu di masa lalu.","formation":"Verb-た-form + ことがある","formationId":"Bentuk kata kerja-た + ことがある","examples":[{"jp":"日本に行ったことがあります。","romaji":"Nihon ni itta koto ga arimasu.","en":"I have been to Japan before.","id":"Saya pernah ke Jepang sebelumnya."},{"jp":"寿司を食べたことがありますか？","romaji":"Sushi wo tabeta koto ga arimasu ka?","en":"Have you ever eaten sushi before?","id":"Pernahkah Anda makan sushi sebelumnya?"},{"jp":"彼はマラソンを走ったことがあります。","romaji":"Kare wa marason wo hashitta koto ga arimasu.","en":"He has experienced running a marathon.","id":"Dia pernah mengalami lari maraton."},{"jp":"私はスカイダイビングをしたことがありません。","romaji":"Watashi wa sukaidaibingu wo shita koto ga arimasen.","en":"I have never experienced skydiving.","id":"Saya belum pernah mengalami terjun payung."}]},{"pattern":"Verb た ときに","meaning":"Express an action or event that occurred at a specific time in the past; 'when', 'at the time'.","meaningId":"Menyatakan suatu tindakan atau peristiwa yang terjadi pada waktu tertentu di masa lalu; 'kapan', 'pada saat itu'.","formation":"Verb-た + ときに","formationId":"Kata Kerja-た + ときに","examples":[{"jp":"映画を見たときに、泣きました。","romaji":"Eiga wo mita toki ni, nakimashita.","en":"When I watched the movie, I cried.","id":"Ketika saya menonton film itu, saya menangis."},{"jp":"彼に初めて会ったときに、遅刻していました。","romaji":"Kare ni hajimete atta toki ni, chikoku shite imashita.","en":"When I first met him, he was late.","id":"Ketika saya pertama kali bertemu dengannya, dia terlambat."},{"jp":"日本へ行ったときに、たくさんの写真を撮りました。","romaji":"Nihon e itta toki ni, takusan no shashin wo torimashita.","en":"When I went to Japan, I took a lot of photos.","id":"Ketika saya pergi ke Jepang, saya mengambil banyak foto."},{"jp":"友達が家に来たときに、ゲームをしました。","romaji":"Tomodachi ga ie ni kita toki ni, geemu wo shimashita.","en":"When my friend came to my house, we played games.","id":"Ketika teman saya datang ke rumah saya, kami bermain game."}]},{"pattern":"Verb た ところ","meaning":"Expresses the situation right after an action has taken place.","meaningId":"Mengekspresikan situasi tepat setelah suatu tindakan dilakukan.","formation":"Verb (た form) + ところ","formationId":"Kata kerja (bentuk た) + ところ","examples":[{"jp":"ドアを開けたところ、猫が飛び出してきた。","romaji":"Doa wo aketa tokoro, neko ga tobidashite kita.","en":"When I opened the door, a cat came jumping out.","id":"Ketika saya membuka pintu, seekor kucing melompat keluar."},{"jp":"電話を切ったところ、また鳴った。","romaji":"Denwa wo kitta tokoro, mata natta.","en":"Right after I hung up the phone, it rang again.","id":"Tepat setelah saya menutup telepon, telepon berdering lagi."},{"jp":"宿題を終わらせたところで、友達から連絡が来た。","romaji":"Shukudai wo owaraseta tokoro de, tomodachi kara renraku ga kita.","en":"Just as I finished my homework, I got a message from my friend.","id":"Saat aku menyelesaikan pekerjaan rumahku, aku mendapat pesan dari temanku."},{"jp":"買い物をして帰ったところ、財布を失くしたことに気づいた。","romaji":"Kaimono wo shite kaetta tokoro, saifu wo nakushita koto ni kizuita.","en":"After shopping and returning home, I realized I had lost my wallet.","id":"Setelah berbelanja dan kembali ke rumah, saya menyadari bahwa saya telah kehilangan dompet saya."}]},{"pattern":"Verb たほうがいい (〜ta hou ga ii)","meaning":"Used to give advice or make a suggestion to someone - 'it's better if...'.","meaningId":"Digunakan untuk memberi nasehat atau saran kepada seseorang - 'lebih baik jika...'.","formation":"Verb (past tense) + ほうがいい","formationId":"Kata kerja (past tense) + ほうがいい","examples":[{"jp":"早く寝たほうがいい。","romaji":"Hayaku neta hou ga ii.","en":"It's better if you go to bed early.","id":"Ada baiknya jika Anda tidur lebih awal."},{"jp":"もっと勉強したほうがいい。","romaji":"Motto benkyou shita hou ga ii.","en":"You should study more.","id":"Anda harus belajar lebih banyak."},{"jp":"病気の時は、薬を飲んだほうがいい。","romaji":"Byouki no toki wa, kusuri wo nonda hou ga ii.","en":"It's a good idea to take medicine when you're sick.","id":"Ada baiknya untuk meminum obat saat Anda sakit."},{"jp":"コーヒーを飲まないほうがいい。","romaji":"Koohii wo nomanai hou ga ii.","en":"It's better if you don't drink coffee.","id":"Lebih baik jika Anda tidak minum kopi."}]},{"pattern":"Verb ために","meaning":"Used to describe the purpose or reason for an action; 'for the sake of', 'in order to', 'because of'.","meaningId":"Digunakan untuk menggambarkan tujuan atau alasan suatu tindakan; 'demi', 'untuk', 'karena'.","formation":"1) Verb (dictionary form) + ために (purpose)\n2) い-Adjective + ために (reason)\n3) な-Adjective + な + ために (reason)\n4) Noun + の + ために (reason)","formationId":"1) Kata kerja (bentuk kamus) + ために (tujuan)\n2) い-Kata sifat + ために (alasan)\n3) な-Kata sifat + な + ために (alasan)\n4) Kata Benda + の + ために (alasan)","examples":[{"jp":"試験に合格するために、毎日勉強しています。","romaji":"Shiken ni goukaku suru tame ni, mainichi benkyou shiteimasu.","en":"I study every day in order to pass the exam.","id":"Saya belajar setiap hari agar bisa lulus ujian."},{"jp":"健康のために、毎日運動しなければなりません。","romaji":"Kenkou no tame ni, mainichi undou shinakereba narimasen.","en":"For the sake of health, I must exercise daily.","id":"Demi kesehatan, saya harus berolahraga setiap hari."},{"jp":"仕事が忙しいために、友達と会う時間がありません。","romaji":"Shigoto ga isogashii tame ni, tomodachi to au jikan ga arimasen.","en":"Because my work is busy, I don't have time to meet friends.","id":"Karena pekerjaan saya sibuk, saya tidak punya waktu untuk bertemu teman."},{"jp":"雨が降ったために、試合が中止されました。","romaji":"Ame ga futta tame ni, shiai ga chuushi saremashita.","en":"The game was canceled because of the rain.","id":"Pertandingan dibatalkan karena hujan."}]},{"pattern":"Verb つもり (〜tsumori)","meaning":"Express the intention, plan, or determination to do something; 'I intend to', 'I plan to', 'I'm determined to'.","meaningId":"Menyatakan niat, rencana, atau tekad untuk melakukan sesuatu; 'Saya bermaksud untuk', 'Saya berencana untuk', 'Saya bertekad untuk'.","formation":"Verb-casual + つもり","formationId":"Kata kerja-kasual + つもり","examples":[{"jp":"明日、友達に会うつもりです。","romaji":"Ashita, tomodachi ni au tsumori desu.","en":"I plan to meet my friend tomorrow.","id":"Aku berencana untuk bertemu temanku besok."},{"jp":"今夜、晩ご飯を作るつもりです。","romaji":"Konya, bangohan o tsukuru tsumori desu.","en":"I intend to cook dinner tonight.","id":"Aku berniat memasak makan malam malam ini."},{"jp":"来年、留学するつもりです。","romaji":"Rainen, ryuugaku suru tsumori desu.","en":"I plan to study abroad next year.","id":"Saya berencana untuk belajar di luar negeri tahun depan."},{"jp":"この週末、山に登るつもりです。","romaji":"Kono shuumatsu, yama ni noboru tsumori desu.","en":"I'm determined to climb the mountain this weekend.","id":"Saya bertekad untuk mendaki gunung akhir pekan ini."}]},{"pattern":"Verb てあげる","meaning":"Used to express doing something for someone; 'do something for someone'.","meaningId":"Digunakan untuk menyatakan melakukan sesuatu untuk seseorang; 'melakukan sesuatu untuk seseorang'.","formation":"Verb-て form + あげる","formationId":"Bentuk kata kerja-て + あげる","examples":[{"jp":"友達が疲れていたから、荷物を持ってあげた。","romaji":"Tomodachi ga tsukareteita kara, nimotsu o motte ageta.","en":"Since my friend was tired, I carried their luggage for them.","id":"Karena teman saya lelah, saya membawakan barang bawaannya untuk mereka."},{"jp":"弟は宿題がわからなかったので、手伝ってあげた。","romaji":"Otouto wa shukudai ga wakaranakatta node, tetsudatte ageta.","en":"My younger brother couldn't understand the homework, so I helped him.","id":"Adik laki-laki saya tidak bisa memahami pekerjaan rumahnya, jadi saya membantunya."},{"jp":"彼女が遅れそうだったから、駅まで迎えに行ってあげた。","romaji":"Kanojo ga okuresou datta kara, eki made mukae ni itte ageta.","en":"She was running late, so I went to pick her up at the station.","id":"Dia terlambat, jadi saya pergi menjemputnya di stasiun."},{"jp":"犬はのどが渇いたそうだったので、水を飲ませてあげた。","romaji":"Inu wa nodo ga kawaita sou datta node, mizu o nomasete ageta.","en":"The dog seemed thirsty, so I gave it water to drink.","id":"Anjing itu tampak haus, jadi saya memberinya air untuk diminum."}]},{"pattern":"Verb て ある (Verb-te aru)","meaning":"Indicates that an action has been done and its result is still in effect.","meaningId":"Menunjukkan bahwa suatu tindakan telah dilakukan dan hasilnya masih berlaku.","formation":"Verb-て form + ある","formationId":"Bentuk kata kerja-て + ある","examples":[{"jp":"窓が開けてある。","romaji":"Mado ga akete aru.","en":"The window has been opened (and remains open).","id":"Jendela telah dibuka (dan tetap terbuka)."},{"jp":"宿題がもう終わってある。","romaji":"Shukudai ga mou owatte aru.","en":"The homework has already been done (and remains that way).","id":"Pekerjaan rumahnya sudah selesai (dan tetap seperti itu)."},{"jp":"洗濯物が全部干してある。","romaji":"Sentakumono ga zenbu hoshite aru.","en":"The laundry has been hung up to dry (and remains that way).","id":"Cucian telah digantung hingga kering (dan tetap seperti itu)."},{"jp":"この部屋はきれいに掃除してある。","romaji":"Kono heya wa kirei ni souji shite aru.","en":"This room has been cleaned (and remains clean).","id":"Ruangan ini telah dibersihkan (dan tetap bersih)."}]},{"pattern":"Verb て いく (Verb-te iku)","meaning":"Expresses an action that continues on into the future or a change that progresses over time.","meaningId":"Mengekspresikan tindakan yang berlanjut di masa depan atau perubahan yang berlangsung seiring waktu.","formation":"Verb in て-form + いく","formationId":"Kata kerja dalam bentuk て + いく","examples":[{"jp":"このまま練習を続けていくと、上達するでしょう。","romaji":"Kono mama renshuu o tsuzukete iku to, joutatsu suru deshou.","en":"If you keep practicing like this, you will improve.","id":"Jika Anda terus berlatih seperti ini, Anda akan meningkat."},{"jp":"彼は成長していくうちに、自立心が強くなった。","romaji":"Kare wa seichou shite iku uchi ni, jiritsushin ga tsuyoku natta.","en":"As he grew up, his independence became stronger.","id":"Seiring bertambahnya usia, kemandiriannya semakin kuat."},{"jp":"この会社はこれからも技術革新を行っていくでしょう。","romaji":"Kono kaisha wa korekara mo gijutsu kakushin o okonatte iku deshou.","en":"This company will continue to innovate in technology in the future.","id":"Perusahaan ini akan terus berinovasi dalam bidang teknologi di masa depan."},{"jp":"子供たちはどんどん学んでいく。","romaji":"Kodomo-tachi wa dondon manande iku.","en":"Children will keep learning more and more.","id":"Anak-anak akan terus belajar lebih banyak lagi."}]},{"pattern":"Verb ていただきたい","meaning":"Express a polite request or desire that someone does something for you.","meaningId":"Ekspresikan permintaan atau keinginan yang sopan agar seseorang melakukan sesuatu untuk Anda.","formation":"Verb-て form + いただきたい","formationId":"Bentuk kata kerja-て + いただきたい","examples":[{"jp":"資料をコピーしていただきたいです。","romaji":"Shiryou wo kopii shite itadakitai desu.","en":"I would like you to make copies of the documents.","id":"Saya ingin Anda membuat salinan dokumen tersebut."},{"jp":"この仕事を手伝っていただきたいのですが。","romaji":"Kono shigoto wo tetsudatte itadakitai no desu ga.","en":"I would like to ask for your assistance with this work.","id":"Saya ingin meminta bantuan Anda dalam pekerjaan ini."},{"jp":"もしよろしければ、指導していただきたいです。","romaji":"Moshi yoroshikereba, shidou shite itadakitai desu.","en":"If it is not too much trouble, I would like you to guide me.","id":"Jika tidak terlalu merepotkan, saya ingin Anda membimbing saya."},{"jp":"駅まで送っていただきたいんですが。","romaji":"Eki made okutte itadakitain desu ga.","en":"I was wondering if you could give me a ride to the station.","id":"Saya ingin tahu apakah Anda bisa memberi saya tumpangan ke stasiun."}]},{"pattern":"Verb ていただく (〜te itadaku)","meaning":"Used to express receiving someone's favor or help; 'to kindly do'.","meaningId":"Digunakan untuk menyatakan menerima bantuan atau bantuan seseorang; 'untuk melakukan dengan baik'.","formation":"Verb-て form + いただく","formationId":"Bentuk kata kerja-て + いただく","examples":[{"jp":"メールを送っていただいて、ありがとうございます。","romaji":"Meeru o okutte itadaite, arigatou gozaimasu.","en":"Thank you for kindly sending the email.","id":"Terima kasih telah berbaik hati mengirimkan email."},{"jp":"荷物を運んでいただいて、助かりました。","romaji":"Nimotsu o hakonde itadaite, tasukarimashita.","en":"You really helped me by carrying the luggage.","id":"Anda sangat membantu saya dengan membawa barang bawaan."},{"jp":"資料をチェックしていただきたいです。","romaji":"Shiryou o chekku shite itadakitai desu.","en":"I would like you to kindly check the documents.","id":"Saya ingin Anda memeriksa dokumennya."},{"jp":"先生にアドバイスをしていただきました。","romaji":"Sensei ni adobaisu o shite itadakimashita.","en":"The teacher kindly gave me advice.","id":"Guru dengan baik hati memberi saya nasihat."}]},{"pattern":"Verb て いただけませんか","meaning":"A polite request; 'Could you please...', 'Would you mind...'","meaningId":"Permintaan yang sopan; 'Bisakah Anda...', 'Maukah Anda...'","formation":"Verb-て form + いただけませんか","formationId":"Bentuk kata kerja-て + いただけませんか","examples":[{"jp":"この手紙を投函していただけませんか。","romaji":"Kono tegami wo toukan shite itadakemasen ka.","en":"Could you please mail this letter for me?","id":"Bisakah Anda mengirimkan surat ini untuk saya?"},{"jp":"この荷物を持っていただけませんか。","romaji":"Kono nimotsu wo motte itadakemasen ka.","en":"Could you please carry this luggage for me?","id":"Bisakah Anda membawakan barang bawaan ini untuk saya?"},{"jp":"隣の部屋にいる人に静かにしていただけませんか。","romaji":"Tonari no heya ni iru hito ni shizuka ni shite itadakemasen ka.","en":"Could you please ask the person next door to be quiet?","id":"Bisakah Anda meminta orang di sebelah untuk diam?"},{"jp":"説明書を読んでいただけませんか。","romaji":"Setsumeisho wo yonde itadakemasen ka.","en":"Could you please read the instruction manual?","id":"Bisakah Anda membaca instruksi manualnya?"}]},{"pattern":"Verb て いる (Verb-te iru)","meaning":"Expresses an ongoing action or a state resulting from a past action.","meaningId":"Mengekspresikan tindakan yang sedang berlangsung atau keadaan yang dihasilkan dari tindakan di masa lalu.","formation":"Verb (て-form) + いる","formationId":"Kata Kerja (て-bentuk) + いる","examples":[{"jp":"今、本を読んでいます。","romaji":"Ima, hon wo yonde imasu.","en":"I am reading a book now.","id":"Saya sedang membaca buku sekarang."},{"jp":"彼は英語を勉強しています。","romaji":"Kare wa eigo wo benkyou shite imasu.","en":"He is studying English.","id":"Dia sedang belajar bahasa Inggris."},{"jp":"ケーキが冷蔵庫に入っています。","romaji":"Keeki ga reizouko ni haitte imasu.","en":"The cake is in the refrigerator.","id":"Kuenya ada di lemari es."},{"jp":"部屋がきれいになっています。","romaji":"Heya ga kirei ni natte imasu.","en":"The room has become clean.","id":"Ruangan menjadi bersih."}]},{"pattern":"Verb て いる ところ","meaning":"Describes an action that is currently happening; 'in the middle of', 'in the process of'.","meaningId":"Menjelaskan suatu tindakan yang sedang terjadi; 'di tengah', 'dalam proses'.","formation":"Verb-て form + いる ところ","formationId":"Bentuk kata kerja-て + いる ところ","examples":[{"jp":"彼は宿題をしているところです。","romaji":"Kare wa shukudai wo shite iru tokoro desu.","en":"He is in the middle of doing his homework.","id":"Dia sedang mengerjakan pekerjaan rumahnya."},{"jp":"私たちは映画を見ているところでした。","romaji":"Watashitachi wa eiga wo mite iru tokoro deshita.","en":"We were in the process of watching a movie.","id":"Kami sedang dalam proses menonton film."},{"jp":"子供たちは公園で遊んでいるところです。","romaji":"Kodomotachi wa kouen de asonde iru tokoro desu.","en":"The kids are in the middle of playing in the park.","id":"Anak-anak sedang bermain di taman."},{"jp":"彼女はケーキを作っているところで、すぐ来ます。","romaji":"Kanojo wa keeki wo tsukutte iru tokoro de, sugu kimasu.","en":"She is in the process of making a cake and will come soon.","id":"Dia sedang dalam proses membuat kue dan akan segera datang."}]},{"pattern":"Verb ている間に","meaning":"Expresses 'while' or 'during the time' something is happening.","meaningId":"Menyatakan 'sementara' atau 'selama' sesuatu sedang terjadi.","formation":"Verb-て form + いる + 間に","formationId":"Bentuk kata kerja-て + いる + 間に","examples":[{"jp":"映画を見ている間に、彼は寝てしまった。","romaji":"Eiga o mite iru aida ni, kare wa nete shimatta.","en":"While watching the movie, he fell asleep.","id":"Saat menonton film, dia tertidur."},{"jp":"子供が遊んでいる間に、私は料理を作ります。","romaji":"Kodomo ga asonde iru aida ni, watashi wa ryouri o tsukurimasu.","en":"While the children are playing, I'll cook.","id":"Selagi anak-anak bermain, saya akan memasak."},{"jp":"会議が行われている間に、雨が降り始めた。","romaji":"Kaigi ga okonawarete iru aida ni, ame ga furihajimeta.","en":"While the meeting was being held, it started raining.","id":"Saat pertemuan sedang berlangsung, hujan mulai turun."},{"jp":"彼が仕事をしている間に、私たちは買い物に行く。","romaji":"Kare ga shigoto o shite iru aida ni, watashitachi wa kaimono ni iku.","en":"While he is working, we'll go shopping.","id":"Selagi dia bekerja, kita akan pergi berbelanja."}]},{"pattern":"Verb ておく (〜te oku)","meaning":"Perform an action in preparation for a future situation; 'to do something in advance'.","meaningId":"Melakukan suatu tindakan sebagai persiapan menghadapi situasi di masa depan; 'to do something in advance'.","formation":"Verb-て form + おく","formationId":"Bentuk kata kerja-て + おく","examples":[{"jp":"駅で切符を買っておこう。","romaji":"Eki de kippu wo katte okou.","en":"Let's buy the tickets in advance at the station.","id":"Ayo beli tiketnya terlebih dahulu di stasiun."},{"jp":"明日早く起きるために、今晩早く寝ておきます。","romaji":"Ashita hayaku okiru tame ni, konban hayaku nete okimasu.","en":"I will go to bed early tonight to wake up early tomorrow.","id":"Saya akan tidur lebih awal malam ini untuk bangun lebih awal besok."},{"jp":"試験前に勉強しておかないと、失敗するかもしれない。","romaji":"Shiken mae ni benkyou shite okanai to, shippai suru kamo shirenai.","en":"If I don't study in advance before the exam, I might fail.","id":"Jika saya tidak belajar terlebih dahulu sebelum ujian, saya mungkin gagal."},{"jp":"彼が到着する前に、部屋をきれいに掃除しておきましょう。","romaji":"Kare ga touchaku suru mae ni, heya wo kirei ni souji shite okimashou.","en":"Let's clean the room before he arrives.","id":"Mari kita bersihkan kamar sebelum dia tiba."}]},{"pattern":"Verb て くださいませんか (Verb-te kudasaimasen ka)","meaning":"Polite request for asking someone for a favor.","meaningId":"Permintaan sopan untuk meminta bantuan seseorang.","formation":"Verb in て-form + くださいませんか","formationId":"Kata kerja dalam bentuk て + くださいませんか","examples":[{"jp":"コーヒーを飲んでくださいませんか。","romaji":"Koohii o nonde kudasaimasen ka.","en":"Would you please drink some coffee?","id":"Maukah kamu minum kopi?"},{"jp":"ドアを閉めてくださいませんか。","romaji":"Doa o shimete kudasaimasen ka.","en":"Would you please close the door?","id":"Tolong tutup pintunya?"},{"jp":"明日お昼に会ってくださいませんか。","romaji":"Ashita ohiru ni atte kudasaimasen ka.","en":"Would you please meet me at lunch tomorrow?","id":"Maukah kamu menemuiku saat makan siang besok?"},{"jp":"その資料を送ってくださいませんか。","romaji":"Sono shiryou o okutte kudasaimasen ka.","en":"Would you please send me that document?","id":"Bisakah Anda mengirimkan saya dokumen itu?"}]},{"pattern":"Verb て くださる (Verb-te kudasaru)","meaning":"Expresses gratitude for receiving someone's favor; 'to kindly do'.","meaningId":"Mengungkapkan rasa terima kasih karena telah menerima bantuan seseorang; 'untuk melakukan dengan baik'.","formation":"Verb て-form + くださる","formationId":"Kata kerja て-bentuk + くださる","examples":[{"jp":"先生が手伝ってくださる。","romaji":"Sensei ga tetsudatte kudasaru.","en":"The teacher kindly helps.","id":"Guru dengan baik hati membantu."},{"jp":"お母さんが美味しい料理を作ってくださる。","romaji":"Okaasan ga oishii ryouri wo tsukutte kudasaru.","en":"My mother kindly cooks delicious meals.","id":"Ibuku dengan baik hati memasak makanan lezat."},{"jp":"友達が私を駅まで送ってくださる。","romaji":"Tomodachi ga watashi wo eki made okutte kudasaru.","en":"My friend kindly gives me a ride to the station.","id":"Teman saya dengan baik hati memberi saya tumpangan ke stasiun."},{"jp":"部長がすぐに質問に答えてくださる。","romaji":"Buchou ga sugu ni shitsumon ni kotaete kudasaru.","en":"The manager kindly answers the questions immediately.","id":"Manajer dengan ramah menjawab pertanyaan dengan segera."}]},{"pattern":"Verb て くる","meaning":"An action that starts in the past and continues to the present or future; 'come to', 'begin to', 'become'.","meaningId":"Suatu tindakan yang dimulai di masa lalu dan berlanjut hingga saat ini atau masa depan; 'datang ke', 'mulai', 'menjadi'.","formation":"Verb て-form + くる","formationId":"Kata kerja て-bentuk + くる","examples":[{"jp":"最近、日本語が分かってくるようになりました。","romaji":"Saikin, nihongo ga wakatte kuru you ni narimashita.","en":"Recently, I've come to understand Japanese.","id":"Baru-baru ini, saya mulai memahami bahasa Jepang."},{"jp":"寒くなってきたので、コートを着ましょう。","romaji":"Samuku natte kita node, kooto wo kimashou.","en":"Since it's gotten cold, let's put on a coat.","id":"Karena cuacanya dingin, ayo pakai mantel."},{"jp":"雨がやんできました。","romaji":"Ame ga yande kimashita.","en":"The rain has stopped (and it's cleared up).","id":"Hujan telah berhenti (dan sudah cerah)."},{"jp":"彼がだんだん怖くなってきた。","romaji":"Kare ga dandan kowaku natte kita.","en":"He has become progressively scarier.","id":"Dia menjadi semakin menakutkan."}]},{"pattern":"Verb てくれませんか (〜te kuremasen ka)","meaning":"A polite way to request someone to do something for you; 'Could you please', 'Would you please', 'Won't you'.","meaningId":"Cara sopan untuk meminta seseorang melakukan sesuatu untuk Anda; 'Bisakah kamu tolong', 'Maukah kamu', 'Maukah kamu'.","formation":"Verb-て form + くれませんか","formationId":"Bentuk kata kerja-て + くれませんか","examples":[{"jp":"ドアを開けてくれませんか。","romaji":"Doa wo akete kuremasen ka.","en":"Could you please open the door?","id":"Bisakah Anda membuka pintunya?"},{"jp":"これを見てくれませんか。","romaji":"Kore wo mite kuremasen ka.","en":"Would you please take a look at this?","id":"Maukah Anda melihat ini?"},{"jp":"手伝ってくれませんか。","romaji":"Tetsudatte kuremasen ka.","en":"Won't you help me?","id":"Maukah kamu membantuku?"},{"jp":"明日、迎えに来てくれませんか。","romaji":"Ashita, mukae ni kite kuremasen ka.","en":"Could you please come to pick me up tomorrow?","id":"Bisakah Anda datang menjemput saya besok?"}]},{"pattern":"Verb て くれる (Verb-te kureru)","meaning":"Expresses that someone does something for the speaker (or another person in speaker's group); 'to do something for me/us'.","meaningId":"Menyatakan bahwa seseorang melakukan sesuatu untuk pembicara (atau orang lain dalam kelompok pembicara); 'melakukan sesuatu untuk saya/kita'.","formation":"Verb-te form + くれる","formationId":"Bentuk kata kerja-te + くれる","examples":[{"jp":"友達が宿題を手伝ってくれました。","romaji":"Tomodachi ga shukudai wo tetsudatte kuremashita.","en":"My friend helped me with my homework.","id":"Teman saya membantu saya mengerjakan pekerjaan rumah saya."},{"jp":"弟が部屋を掃除してくれた。","romaji":"Otouto ga heya wo souji shite kureta.","en":"My younger brother cleaned the room for me.","id":"Adik laki-laki saya membersihkan kamar untuk saya."},{"jp":"先生が質問に答えてくれます。","romaji":"Sensei ga shitsumon ni kotaete kuremasu.","en":"The teacher answers my questions for me.","id":"Guru menjawab pertanyaan saya untuk saya."},{"jp":"彼女が手紙を書いてくれる。","romaji":"Kanojo ga tegami wo kaite kureru.","en":"She writes a letter for me.","id":"Dia menulis surat untukku."}]},{"pattern":"Verb て + さしあげる","meaning":"A polite way to express giving or doing something for someone.","meaningId":"Cara sopan untuk menyatakan memberi atau melakukan sesuatu untuk seseorang.","formation":"Verb-てform + さしあげる","formationId":"Bentuk kata kerja-て + さしあげる","examples":[{"jp":"お茶を入れてさしあげます。","romaji":"Ocha wo irete sashiagemasu.","en":"I will prepare and serve tea (for you).","id":"Saya akan menyiapkan dan menyajikan teh (untuk Anda)."},{"jp":"メッセージを送ってさしあげました。","romaji":"Messeiji wo okutte sashiagemashita.","en":"I have sent the message (for you).","id":"Saya telah mengirimkan pesan (untuk Anda)."},{"jp":"荷物を持ってさしあげましょうか。","romaji":"Nimotsu wo motte sashiagemashou ka.","en":"Shall I carry the luggage (for you)?","id":"Bolehkah saya membawakan barang bawaannya (untuk Anda)?"},{"jp":"お電話をかけてさしあげます。","romaji":"Odenwa wo kakete sashiagemasu.","en":"I will make a phone call (for you).","id":"Saya akan menelepon (untuk Anda)."}]},{"pattern":"Verb てしまう (〜te shimau)","meaning":"Expresses unintentional actions or actions with regrettable outcomes; 'to end up doing', 'to accidentally do'.","meaningId":"Mengekspresikan tindakan yang tidak disengaja atau tindakan dengan hasil yang disesalkan; 'akhirnya melakukan', 'tidak sengaja melakukan'.","formation":"Verb-te form + しまう","formationId":"Bentuk kata kerja-te + しまう","examples":[{"jp":"ケーキを全部食べてしまった。","romaji":"Keeki wo zenbu tabete shimatta.","en":"I ended up eating the whole cake.","id":"Saya akhirnya memakan seluruh kuenya."},{"jp":"宿題を忘れてしまいました。","romaji":"Shukudai wo wasurete shimaimashita.","en":"I accidentally forgot my homework.","id":"Saya tidak sengaja lupa pekerjaan rumah saya."},{"jp":"彼に秘密を言ってしまった。","romaji":"Kare ni himitsu wo itte shimatta.","en":"I accidentally told him the secret.","id":"Saya tidak sengaja menceritakan rahasianya kepadanya."},{"jp":"値札を見ずに高い服を買ってしまった。","romaji":"Nefuda wo mizu ni takai fuku wo katte shimatta.","en":"I ended up buying expensive clothes without looking at the price tag.","id":"Saya akhirnya membeli pakaian mahal tanpa melihat label harganya."}]},{"pattern":"Verb て ほしい (Verb-te hoshii)","meaning":"Express a desire for someone else to do something; 'I want (someone) to'.","meaningId":"Ekspresikan keinginan agar orang lain melakukan sesuatu; 'Saya ingin (seseorang) melakukannya'.","formation":"Verb-て form + ほしい","formationId":"Bentuk kata kerja-て + ほしい","examples":[{"jp":"子供にもっと勉強してほしい。","romaji":"Kodomo ni motto benkyou shite hoshii.","en":"I want my child to study more.","id":"Saya ingin anak saya belajar lebih banyak."},{"jp":"彼にもっと早く来てほしい。","romaji":"Kare ni motto hayaku kite hoshii.","en":"I want him to come earlier.","id":"Saya ingin dia datang lebih awal."},{"jp":"友達にその本を読んでほしい。","romaji":"Tomodachi ni sono hon o yonde hoshii.","en":"I want my friend to read that book.","id":"Saya ingin teman saya membaca buku itu."},{"jp":"先生に質問に答えてほしい。","romaji":"Sensei ni shitsumon ni kotaete hoshii.","en":"I want the teacher to answer the question.","id":"Saya ingin guru menjawab pertanyaan itu."}]},{"pattern":"Verb てみる (〜te miru)","meaning":"Used to express 'try to' or 'attempt to do'.","meaningId":"Digunakan untuk menyatakan 'mencoba' atau 'mencoba melakukan'.","formation":"Verb-て form + みる","formationId":"Bentuk kata kerja-て + みる","examples":[{"jp":"この料理を作ってみます。","romaji":"Kono ryouri o tsukutte mimasu.","en":"I will try to make this dish.","id":"Saya akan mencoba membuat hidangan ini."},{"jp":"その服を着てみてください。","romaji":"Sono fuku o kite mite kudasai.","en":"Please try on those clothes.","id":"Silakan coba pakaian itu."},{"jp":"新しいレストランに行ってみよう。","romaji":"Atarashii resutoran ni itte miyou.","en":"Let's try going to the new restaurant.","id":"Ayo coba pergi ke restoran baru."},{"jp":"映画を見てみたいです。","romaji":"Eiga o mite mitai desu.","en":"I want to try watching the movie.","id":"Saya ingin mencoba menonton filmnya."}]},{"pattern":"Verb てもらいたい","meaning":"Express a desire to receive a favor or service from someone else.","meaningId":"Mengungkapkan keinginan untuk menerima bantuan atau layanan dari orang lain.","formation":"Verb-て-form + もらいたい","formationId":"Bentuk kata kerja-て + もらいたい","examples":[{"jp":"この荷物を運んでもらいたいです。","romaji":"Kono nimotsu o hakonde moraitai desu.","en":"I want you to carry this luggage for me.","id":"Saya ingin Anda membawakan barang bawaan ini untuk saya."},{"jp":"彼にそのニュースを教えてもらいたい。","romaji":"Kare ni sono nyuusu o oshiete moraitai.","en":"I want him to tell me the news.","id":"Aku ingin dia memberitahuku kabar itu."},{"jp":"友達に日本語を教えてもらいたい。","romaji":"Tomodachi ni Nihongo o oshiete moraitai.","en":"I want my friend to teach me Japanese.","id":"Saya ingin teman saya mengajari saya bahasa Jepang."},{"jp":"スタッフにチェックインの方法を説明してもらいたい。","romaji":"Sutaffu ni chekkuin no houhou o setsumei shite moraitai.","en":"I want the staff to explain the check-in process to me.","id":"Saya ingin staf menjelaskan proses check-in kepada saya."}]},{"pattern":"Verb て もらう (Verb-te morau)","meaning":"Express receiving a favor or action from someone.","meaningId":"Ekspresikan menerima bantuan atau tindakan dari seseorang.","formation":"Verb-て form + もらう","formationId":"Bentuk kata kerja-て + もらう","examples":[{"jp":"友達に宿題を手伝ってもらった。","romaji":"Tomodachi ni shukudai o tetsudatte moratta.","en":"I had my friend help me with my homework.","id":"Saya meminta teman saya membantu saya mengerjakan pekerjaan rumah saya."},{"jp":"母に部屋を掃除してもらいました。","romaji":"Haha ni heya o souji shite moraimashita.","en":"I had my mother clean my room.","id":"Aku menyuruh ibuku membersihkan kamarku."},{"jp":"彼に荷物を持ってもらいたい。","romaji":"Kare ni nimotsu o motte moraitai.","en":"I want him to carry my luggage for me.","id":"Saya ingin dia membawakan barang bawaan saya untuk saya."},{"jp":"先生に質問に答えてもらえますか？","romaji":"Sensei ni shitsumon ni kotaete moraemasu ka?","en":"Can I have the teacher answer my question?","id":"Bisakah saya meminta guru menjawab pertanyaan saya?"}]},{"pattern":"Verb てもらえませんか","meaning":"A polite way to ask for a favor or request someone to do something.","meaningId":"Cara sopan untuk meminta bantuan atau meminta seseorang melakukan sesuatu.","formation":"Verb-て form + もらえませんか","formationId":"Bentuk kata kerja-て + もらえませんか","examples":[{"jp":"この手紙を見てもらえませんか。","romaji":"Kono tegami o mite moraemasen ka?","en":"Could you take a look at this letter for me?","id":"Bisakah Anda melihat surat ini untuk saya?"},{"jp":"荷物を持ってもらえませんか。","romaji":"Nimotsu o motte moraemasen ka?","en":"Could you carry this luggage for me?","id":"Bisakah Anda membawakan barang bawaan ini untuk saya?"},{"jp":"部屋を掃除してもらえませんか。","romaji":"Heya o souji shite moraemasen ka?","en":"Could you clean the room for me?","id":"Bisakah kamu membersihkan kamar untukku?"},{"jp":"明日のミーティングに参加してもらえませんか。","romaji":"Ashita no miitingu ni sanka shite moraemasen ka?","en":"Could you attend tomorrow's meeting for me?","id":"Bisakah Anda menghadiri pertemuan besok untuk saya?"}]},{"pattern":"Verb ない ことがある (Verb-nai koto ga aru)","meaning":"Expresses that something doesn't always happen or there are occasions when it doesn't happen.","meaningId":"Mengungkapkan bahwa sesuatu tidak selalu terjadi atau ada kalanya hal itu tidak terjadi.","formation":"Verb-negative form + ことがある","formationId":"Bentuk kata kerja negatif + ことがある","examples":[{"jp":"彼は会議に出席しないことがある。","romaji":"Kare wa kaigi ni shusseki shinai koto ga aru.","en":"There are times when he doesn't attend meetings.","id":"Ada kalanya dia tidak menghadiri rapat."},{"jp":"この電車は定刻に来ないことがある。","romaji":"Kono densha wa teikoku ni konai koto ga aru.","en":"There are occasions when this train doesn't come on time.","id":"Ada kalanya kereta ini tidak datang tepat waktu."},{"jp":"私は朝食を食べないことがある。","romaji":"Watashi wa choushoku o tabenai koto ga aru.","en":"There are times when I don't eat breakfast.","id":"Ada kalanya saya tidak sarapan."},{"jp":"彼女は電話に出ないことがある。","romaji":"Kanojo wa denwa ni denai koto ga aru.","en":"There are occasions when she doesn't answer the phone.","id":"Ada kalanya dia tidak menjawab telepon."}]},{"pattern":"Verb ない + ことにする","meaning":"To decide not to do something.","meaningId":"Untuk memutuskan untuk tidak melakukan sesuatu.","formation":"Verb-ない form + ことにする","formationId":"Bentuk kata kerja-ない + ことにする","examples":[{"jp":"明日のパーティーに行かないことにする。","romaji":"Ashita no paatii ni ikanai koto ni suru.","en":"I've decided not to go to tomorrow's party.","id":"Saya telah memutuskan untuk tidak pergi ke pesta besok."},{"jp":"そのケーキを食べないことにします。","romaji":"Sono keeki wo tabenai koto ni shimasu.","en":"I've decided not to eat that cake.","id":"Aku sudah memutuskan untuk tidak memakan kue itu."},{"jp":"今日はジョギングをしないことにする。","romaji":"Kyou wa jogingu wo shinai koto ni suru.","en":"I've decided not to go jogging today.","id":"Aku memutuskan untuk tidak jogging hari ini."},{"jp":"彼と会わないことにしました。","romaji":"Kare to awanai koto ni shimashita.","en":"I've decided not to meet him.","id":"Aku sudah memutuskan untuk tidak bertemu dengannya."}]},{"pattern":"Verb ない ことになる","meaning":"Expresses a result; 'end up not', 'it will become that', 'it would mean that'.","meaningId":"Mengekspresikan hasil; 'berakhir tidak', 'akan menjadi seperti itu', 'berarti begitu'.","formation":"Verb-negative (ない) + ことになる","formationId":"Kata kerja-negatif (ない) + ことになる","examples":[{"jp":"今日彼が来ないことになると、私たちの予定はキャンセルされます。","romaji":"Kyou kare ga konai koto ni naru to, watashitachi no yotei wa kyanseru saremasu.","en":"If he doesn't come today, our plans will be canceled.","id":"Jika dia tidak datang hari ini, rencana kita akan dibatalkan."},{"jp":"このプロジェクトが進まないことになると、収益が減るでしょう。","romaji":"Kono purojekuto ga susumanai koto ni naru to, shuueki ga heru deshou.","en":"If this project doesn't progress, it would mean that revenue will decrease.","id":"Jika proyek ini tidak berjalan, berarti pendapatan akan berkurang."},{"jp":"彼女は試験に合格しないことになると、卒業が遅れます。","romaji":"Kanojo wa shiken ni goukaku shinai koto ni naru to, sotsugyou ga okuremasu.","en":"If she ends up not passing the exam, her graduation will be delayed.","id":"Jika dia akhirnya tidak lulus ujian, kelulusannya akan tertunda."},{"jp":"雨が降ると、ピクニックが行われないことになるでしょう。","romaji":"Ame ga furu to, pikunikku ga okonawarenai koto ni naru deshou.","en":"If it rains, it will become that the picnic doesn't take place.","id":"Jika hujan maka piknik tidak akan terlaksana."}]},{"pattern":"Verb ないほうがいい","meaning":"Expresses the idea that it is better not to do something.","meaningId":"Mengungkapkan gagasan bahwa lebih baik tidak melakukan sesuatu.","formation":"Verb-negative form + ほうがいい","formationId":"Bentuk kata kerja negatif + ほうがいい","examples":[{"jp":"この薬は飲まないほうがいいです。","romaji":"Kono kusuri wa nomanai hou ga ii desu.","en":"It's better not to take this medicine.","id":"Lebih baik tidak meminum obat ini."},{"jp":"急いでいるときは、走らないほうがいい。","romaji":"Isoide iru toki wa, hashiranai hou ga ii.","en":"When you're in a hurry, it's better not to run.","id":"Saat Anda sedang terburu-buru, lebih baik jangan lari."},{"jp":"彼に秘密を知られたくなければ、話さないほうがいい。","romaji":"Kare ni himitsu o shiraretakunakereba, hanasanai hou ga ii.","en":"If you don't want him to know your secret, it's better not to tell him.","id":"Jika kamu tidak ingin dia mengetahui rahasiamu, lebih baik jangan beritahu dia."},{"jp":"雨の日には、外出しないほうがいい。","romaji":"Ame no hi ni wa, gaishutsu shinai hou ga ii.","en":"It's better not to go out on a rainy day.","id":"Lebih baik tidak keluar pada hari hujan."}]},{"pattern":"Verb ながら (〜nagara)","meaning":"Expresses 'while' or 'as' in the sense of doing two things simultaneously.","meaningId":"Mengekspresikan 'sementara' atau 'sebagai' dalam arti melakukan dua hal secara bersamaan.","formation":"Verb-masu stem + ながら","formationId":"Kata kerja-masu batang + ながら","examples":[{"jp":"テレビを見ながら宿題をしました。","romaji":"Terebi wo minagara shukudai wo shimashita.","en":"I did my homework while watching television.","id":"Saya mengerjakan pekerjaan rumah saya sambil menonton televisi."},{"jp":"音楽を聞きながら料理をしました。","romaji":"Ongaku wo kikinagara ryouri wo shimashita.","en":"I cooked while listening to music.","id":"Saya memasak sambil mendengarkan musik."},{"jp":"歩きながらスマホを見るのは危険です。","romaji":"Arukinagara sumaho wo miru no wa kiken desu.","en":"Looking at your smartphone while walking is dangerous.","id":"Melihat ponsel pintar sambil berjalan itu berbahaya."},{"jp":"彼は話しながら笑っていました。","romaji":"Kare wa hanashi nagara waratte imashita.","en":"He was laughing while talking.","id":"Dia tertawa sambil berbicara."}]},{"pattern":"Verb なさい (〜nasai)","meaning":"A command form used to give orders or instructions; 'Please do', 'Do this'.","meaningId":"Bentuk perintah yang digunakan untuk memberi perintah atau instruksi; 'Tolong lakukan', 'Lakukan ini'.","formation":"Verb-stem + なさい","formationId":"Batang kata kerja + なさい","examples":[{"jp":"部屋を掃除しなさい。","romaji":"Heya wo souji shinasai.","en":"Clean your room.","id":"Bersihkan kamarmu."},{"jp":"勉強しなさい。","romaji":"Benkyou shinasai.","en":"Study.","id":"Belajar."},{"jp":"早く起きなさい。","romaji":"Hayaku okinasai.","en":"Wake up early.","id":"Bangun lebih awal."},{"jp":"宿題をやりなさい。","romaji":"Shukudai wo yarinasai.","en":"Do your homework.","id":"Kerjakan pekerjaan rumahmu."}]},{"pattern":"Verb にくい (〜nikui)","meaning":"Express difficulty or complexity; 'hard to', 'difficult to', 'not easily'.","meaningId":"Nyatakan kesulitan atau kerumitan; 'sulit untuk', 'sulit untuk', 'tidak mudah'.","formation":"Verb-stem + にくい","formationId":"Batang kata kerja + にくい","examples":[{"jp":"この字は読みにくいです。","romaji":"Kono ji wa yomi nikui desu.","en":"This character is hard to read.","id":"Karakter ini sulit dibaca."},{"jp":"このドアは開けにくい。","romaji":"Kono doa wa ake nikui.","en":"This door is difficult to open.","id":"Pintu ini sulit dibuka."},{"jp":"彼の字は読みにくい。","romaji":"Kare no ji wa yomi nikui.","en":"His handwriting is hard to read.","id":"Tulisan tangannya sulit dibaca."},{"jp":"この料理は作りにくい。","romaji":"Kono ryouri wa tsukuri nikui.","en":"This dish is difficult to make.","id":"Hidangan ini sulit dibuat."}]},{"pattern":"Verb やすい (〜yasui)","meaning":"Indicates that something is easy to do; 'easy to', 'easy for'.","meaningId":"Menunjukkan bahwa sesuatu itu mudah dilakukan; 'mudah untuk', 'mudah untuk'.","formation":"Verb-stem + やすい","formationId":"Batang kata kerja + やすい","examples":[{"jp":"この本は読みやすいです。","romaji":"Kono hon wa yomiyasui desu.","en":"This book is easy to read.","id":"Buku ini mudah dibaca."},{"jp":"このシャツは着やすい。","romaji":"Kono shatsu wa kiyasui.","en":"This shirt is easy to wear.","id":"Kemeja ini mudah dipakai."},{"jp":"彼は話しやすい人です。","romaji":"Kare wa hanashiyasui hito desu.","en":"He is an easy person to talk to.","id":"Dia adalah orang yang mudah diajak bicara."},{"jp":"この料理は作りやすい。","romaji":"Kono ryouri wa tsukuriyasui.","en":"This dish is easy to make.","id":"Hidangan ini mudah dibuat."}]},{"pattern":"Verb ようと思う (Verb-you to omou)","meaning":"Express intention or plan to do something; 'I think I will', 'I plan to', 'I intend to'.","meaningId":"Mengungkapkan niat atau rencana untuk melakukan sesuatu; 'Saya pikir saya akan melakukannya', 'Saya berencana untuk', 'Saya berniat untuk'.","formation":"Verb-volitional + と思う","formationId":"Kata kerja-kehendak + と思う","examples":[{"jp":"明日、映画を見ようと思います。","romaji":"Ashita, eiga o miyou to omoimasu.","en":"I think I will watch a movie tomorrow.","id":"Saya pikir saya akan menonton film besok."},{"jp":"週末に友達と遊ぼうと思っています。","romaji":"Shuumatsu ni tomodachi to asobou to omotteimasu.","en":"I plan to hang out with friends on the weekend.","id":"Saya berencana untuk berkumpul dengan teman-teman di akhir pekan."},{"jp":"勉強をもっと頑張ろうと思う。","romaji":"Benkyou o motto ganbarou to omou.","en":"I intend to study harder.","id":"Saya berniat untuk belajar lebih giat."},{"jp":"来年は海外旅行に行こうと思っている。","romaji":"Rainen wa kaigai ryokou ni ikou to omotteiru.","en":"I plan to go on an overseas trip next year.","id":"Saya berencana melakukan perjalanan ke luar negeri tahun depan."}]},{"pattern":"Verb ように (〜you ni)","meaning":"Used to express 'like', 'as if', 'in order to', or 'so that'.","meaningId":"Digunakan untuk menyatakan 'seperti', 'seolah-olah', 'untuk', atau 'sehingga'.","formation":"Examples: Noun + のように / Verb-casual + ように / い-adjective + ように","formationId":"Contoh: Kata Benda + のように / Kata Kerja-kasual + ように / い-kata sifat + ように","examples":[{"jp":"彼女は鳥のように軽やかに踊る。","romaji":"Kanojo wa tori no you ni karoyaka ni odoru.","en":"She dances lightly like a bird.","id":"Dia menari dengan ringan seperti burung."},{"jp":"覚えたことを忘れないように、毎日復習しましょう。","romaji":"Oboeta koto wo wasurenai you ni, mainichi fukushuu shimashou.","en":"In order not to forget what you've learned, let's review every day.","id":"Agar tidak melupakan apa yang telah Anda pelajari, mari kita ulas setiap hari."},{"jp":"歌手になるように、毎日歌の練習をしています。","romaji":"Kashu ni naru you ni, mainichi uta no renshuu wo shiteimasu.","en":"In order to become a singer, I practice singing every day.","id":"Untuk menjadi seorang penyanyi, saya berlatih menyanyi setiap hari."},{"jp":"道を渡る時、車が来ないように確認してください。","romaji":"Michi wo wataru toki, kuruma ga konai you ni kakunin shite kudasai.","en":"When crossing the road, please make sure no cars are coming.","id":"Saat menyeberang jalan, pastikan tidak ada mobil yang lewat."}]},{"pattern":"Verb ようにする","meaning":"Make an effort to; try to; see to it that; ensure that.","meaningId":"Berusahalah untuk; mencoba untuk; pastikan bahwa; memastikan itu.","formation":"Verb-dictionary form + ようにする","formationId":"Bentuk kamus kata kerja + ようにする","examples":[{"jp":"毎日運動するようにしています。","romaji":"Mainichi undou suru you ni shiteimasu.","en":"I try to exercise every day.","id":"Saya mencoba berolahraga setiap hari."},{"jp":"早く寝るようにしてください。","romaji":"Hayaku neru you ni shite kudasai.","en":"Please try to go to bed early.","id":"Silakan mencoba untuk tidur lebih awal."},{"jp":"約束を守るようにします。","romaji":"Yakusoku o mamoru you ni shimasu.","en":"I will make sure to keep my promise.","id":"Aku akan memastikan untuk menepati janjiku."},{"jp":"彼に会わないようにする。","romaji":"Kare ni awanai you ni suru.","en":"I will try not to see him.","id":"Saya akan mencoba untuk tidak melihatnya."}]},{"pattern":"Verb ようになる (〜you ni naru)","meaning":"Express a change in ability, situation or state; 'become able to', 'come to', 'begin to'.","meaningId":"Menyatakan perubahan kemampuan, situasi atau keadaan; 'menjadi mampu', 'sampai pada', 'mulai'.","formation":"Verb-dictionary/potential form + ようになる","formationId":"Kamus kata kerja/bentuk potensial + ようになる","examples":[{"jp":"日本語が話せるようになりました。","romaji":"Nihongo ga hanaseru you ni narimashita.","en":"I have become able to speak Japanese.","id":"Saya sudah bisa berbicara bahasa Jepang."},{"jp":"最近、早く寝るようになった。","romaji":"Saikin, hayaku neru you ni natta.","en":"Recently, I have come to go to bed early.","id":"Baru-baru ini, saya datang untuk tidur lebih awal."},{"jp":"彼はピアノを弾けるようになりました。","romaji":"Kare wa piano wo hikeru you ni narimashita.","en":"He has become able to play the piano.","id":"Dia sudah bisa bermain piano."},{"jp":"この仕事を始めてから、毎日忙しいと感じるようになりました。","romaji":"Kono shigoto o hajimete kara, mainichi isogashii to kanjiru you ni narimashita.","en":"Since I started this job, I've begun to feel busy every day.","id":"Sejak saya memulai pekerjaan ini, saya mulai merasa sibuk setiap hari."}]},{"pattern":"Verb ように言う (Verb-you ni iu)","meaning":"Tell someone to do something; 'tell to do', 'instruct to do'.","meaningId":"Suruh seseorang melakukan sesuatu; 'suruh melakukan', 'perintahkan untuk melakukan'.","formation":"Verb-casual + ように言う","formationId":"Kata kerja-kasual + ように言う","examples":[{"jp":"先生は私たちに宿題をやるように言いました。","romaji":"Sensei wa watashitachi ni shukudai o yaru you ni iimashita.","en":"The teacher told us to do our homework.","id":"Guru menyuruh kami mengerjakan pekerjaan rumah kami."},{"jp":"母は弟に部屋を片付けるように言いました。","romaji":"Haha wa otouto ni heya wo katazukeru you ni iimashita.","en":"My mother told my younger brother to clean his room.","id":"Ibuku menyuruh adik laki-lakiku untuk membersihkan kamarnya."},{"jp":"上司は私に報告書を提出するように言いました。","romaji":"Joushi wa watashi ni houkokusho wo teishutsu suru you ni iimashita.","en":"My boss told me to submit the report.","id":"Bos saya menyuruh saya untuk menyerahkan laporan."},{"jp":"友達が私に早く来るように言いました。","romaji":"Tomodachi ga watashi ni hayaku kuru you ni iimashita.","en":"My friend told me to come early.","id":"Temanku menyuruhku untuk datang lebih awal."}]},{"pattern":"Verb られる (〜rareru)","meaning":"Expresses passive voice or potential form for verbs.","meaningId":"Mengekspresikan kalimat pasif atau bentuk potensial untuk kata kerja.","formation":"う-verb (passive): Replace the final う with われる / る-verb (passive & potential): Replace る with られる / Irregular: する → される, くる → こられる","formationId":"Kata kerja う (pasif): Gantikan う akhir dengan われる / る-kata kerja (pasif & potensial): Ganti る dengan られる / Tidak Beraturan: する → される, くる → こられる","examples":[{"jp":"彼は先生に褒められました。","romaji":"Kare wa sensei ni homeraremashita.","en":"He was praised by the teacher.","id":"Dia dipuji oleh gurunya."},{"jp":"彼は友達に笑われました。","romaji":"Kare wa tomodachi ni warawaremashita.","en":"He was laughed at by his friends.","id":"Dia ditertawakan oleh teman-temannya."},{"jp":"映画は観られましたか？","romaji":"Eiga wa miraremashita ka?","en":"Were you able to watch the movie?","id":"Apakah Anda dapat menonton filmnya?"},{"jp":"彼女はリーダーに選ばれました。","romaji":"Kanojo wa riidaa ni erabaremashita.","en":"She was chosen as the leader.","id":"Dia terpilih sebagai pemimpin."}]},{"pattern":"Verb る ことがある (〜ru koto ga aru)","meaning":"Used to express that something happens sometimes or has happened before.","meaningId":"Digunakan untuk menyatakan bahwa sesuatu terjadi kadang-kadang atau telah terjadi sebelumnya.","formation":"Verb-dictionary form + ことがある","formationId":"Bentuk kamus kata kerja + ことがある","examples":[{"jp":"彼は遅刻することがあります。","romaji":"Kare wa chikoku suru koto ga arimasu.","en":"He is sometimes late.","id":"Dia terkadang terlambat."},{"jp":"私は寝坊することがあります。","romaji":"Watashi wa nebou suru koto ga arimasu.","en":"I sometimes oversleep.","id":"Saya terkadang ketiduran."},{"jp":"彼女は歌を歌うことがあります。","romaji":"Kanojo wa uta o utau koto ga arimasu.","en":"She sometimes sings songs.","id":"Dia terkadang menyanyikan lagu."},{"jp":"子供の頃、よく山に登ることがありました。","romaji":"Kodomo no koro, yoku yama ni noboru koto ga arimashita.","en":"When I was a child, I sometimes climbed mountains.","id":"Ketika saya masih kecil, saya terkadang mendaki gunung."}]},{"pattern":"Verb ることができる (〜ru koto ga dekiru)","meaning":"Express ability or possibility of doing an action; 'can', 'be able to', 'is possible'.","meaningId":"Mengungkapkan kemampuan atau kemungkinan melakukan suatu tindakan; 'bisa', 'bisa', 'mungkin'.","formation":"Verb-る + ことができる","formationId":"Kata kerja-る + ことができる","examples":[{"jp":"私は日本語を話すことができます。","romaji":"Watashi wa nihongo wo hanasu koto ga dekimasu.","en":"I can speak Japanese.","id":"Saya bisa berbicara bahasa Jepang."},{"jp":"彼はギターを弾くことができます。","romaji":"Kare wa gitaa wo hiku koto ga dekimasu.","en":"He can play the guitar.","id":"Dia bisa bermain gitar."},{"jp":"この問題を解決することができますか？","romaji":"Kono mondai wo kaiketsu suru koto ga dekimasu ka?","en":"Can you solve this problem?","id":"Bisakah Anda mengatasi masalah ini?"},{"jp":"彼女は犬を泳がせることができます。","romaji":"Kanojo wa inu wo oyogaseru koto ga dekimasu.","en":"She can make the dog swim.","id":"Dia bisa membuat anjingnya berenang."}]},{"pattern":"Verb ることにする (〜ru koto ni suru)","meaning":"Decide to do something, make a decision.","meaningId":"Putuskan untuk melakukan sesuatu, buatlah keputusan.","formation":"Verb-る + ことにする","formationId":"Kata kerja-る + ことにする","examples":[{"jp":"来週、ジムに行くことにしました。","romaji":"Raishuu, jimu ni iku koto ni shimashita.","en":"I decided to go to the gym next week.","id":"Saya memutuskan untuk pergi ke gym minggu depan."},{"jp":"この靴を買うことにしました。","romaji":"Kono kutsu wo kau koto ni shimashita.","en":"I decided to buy these shoes.","id":"Saya memutuskan untuk membeli sepatu ini."},{"jp":"毎日、散歩をすることにしました。","romaji":"Mainichi, sanpo wo suru koto ni shimashita.","en":"I decided to take a walk every day.","id":"Saya memutuskan untuk berjalan-jalan setiap hari."},{"jp":"彼に電話をかけることにします。","romaji":"Kare ni denwa wo kakeru koto ni shimasu.","en":"I’ve decided to call him.","id":"Saya telah memutuskan untuk meneleponnya."}]},{"pattern":"Verb る ことになる (〜ru koto ni naru)","meaning":"Indicates that something has been decided or arranged; 'it has been decided that', 'it turns out that'.","meaningId":"Menunjukkan bahwa sesuatu telah diputuskan atau diatur; 'sudah diputuskan itu', 'ternyata begitu'.","formation":"Verb-る + ことになる","formationId":"Kata kerja-る + ことになる","examples":[{"jp":"今日は会議がなくなることになりました。","romaji":"Kyou wa kaigi ga nakunaru koto ni narimashita.","en":"It has been decided that there will be no meeting today.","id":"Telah diputuskan bahwa tidak akan ada pertemuan hari ini."},{"jp":"来週、友達と旅行することになった。","romaji":"Raishuu, tomodachi to ryokou suru koto ni natta.","en":"It has been arranged that I will travel with my friends next week.","id":"Telah diatur bahwa saya akan bepergian dengan teman-teman saya minggu depan."},{"jp":"彼女が今度のプロジェクトのリーダーになることになりました。","romaji":"Kanojo ga kondo no purojekuto no riida ni naru koto ni narimashita.","en":"It has been decided that she will be the leader of the next project.","id":"Telah diputuskan bahwa dia akan menjadi pemimpin proyek berikutnya."},{"jp":"急に仕事が入ったので、休みを取ることになった。","romaji":"Kyuu ni shigoto ga haitta node, yasumi wo toru koto ni natta.","en":"Due to sudden work, it has been decided that I will take a day off.","id":"Karena pekerjaan yang tiba-tiba, diputuskan bahwa saya akan mengambil cuti."}]},{"pattern":"Verb るときに (〜ru toki ni)","meaning":"Describes the time when a certain action takes place; 'when', 'at the time'.","meaningId":"Menjelaskan waktu terjadinya tindakan tertentu; 'kapan', 'pada saat itu'.","formation":"Verb-る + ときに","formationId":"Kata kerja-る + ときに","examples":[{"jp":"映画を見るときに、ポップコーンを食べます。","romaji":"Eiga wo miru toki ni, poppukoon wo tabemasu.","en":"When I watch a movie, I eat popcorn.","id":"Saat saya menonton film, saya makan popcorn."},{"jp":"寝るときに、部屋の電気を消します。","romaji":"Neru toki ni, heya no denki wo keshimasu.","en":"When I go to bed, I turn off the room lights.","id":"Ketika saya pergi tidur, saya mematikan lampu kamar."},{"jp":"運動するときに、水分補給が大切です。","romaji":"Undou suru toki ni, suibun hokyuu ga taisetsu desu.","en":"When exercising, it's important to stay hydrated.","id":"Saat berolahraga, penting untuk tetap terhidrasi."},{"jp":"旅行するときに、カメラを持っていくことが好きです。","romaji":"Ryokou suru toki ni, kamera wo motteiku koto ga suki desu.","en":"When I travel, I like to bring a camera.","id":"Saat saya bepergian, saya suka membawa kamera."}]},{"pattern":"Verb る ところ (Verb-ru tokoro)","meaning":"Expresses the state or moment when an action is about to happen or is happening.","meaningId":"Menyatakan keadaan atau momen ketika suatu tindakan akan terjadi atau sedang terjadi.","formation":"Verb-dictionary form + ところ","formationId":"Bentuk kamus kata kerja + ところ","examples":[{"jp":"彼は食べるところです。","romaji":"Kare wa taberu tokoro desu.","en":"He is in the process of eating.","id":"Dia sedang dalam proses makan."},{"jp":"私は出かけるところです。","romaji":"Watashi wa dekakeru tokoro desu.","en":"I am just about to leave.","id":"Saya baru saja akan pergi."},{"jp":"彼女は泣くところでした。","romaji":"Kanojo wa naku tokoro deshita.","en":"She was on the verge of crying.","id":"Dia hampir menangis."},{"jp":"私たちは勉強するところです。","romaji":"Watashitachi wa benkyou suru tokoro desu.","en":"We are in the middle of studying.","id":"Kami sedang belajar."}]},{"pattern":"Verb 出す","meaning":"Express the action of taking something out, starting an action, or emphasizing a verb.","meaningId":"Ekspresikan tindakan mengeluarkan sesuatu, memulai suatu tindakan, atau menekankan kata kerja.","formation":"Verb stem + 出す (~dasu)","formationId":"Batang kata kerja + 出す (~dasu)","examples":[{"jp":"本を棚から出してください。","romaji":"Hon o tana kara dashite kudasai.","en":"Please take the book out from the shelf.","id":"Tolong keluarkan buku itu dari rak."},{"jp":"彼は部屋から急いで出ました。","romaji":"Kare wa heya kara isoide demashita.","en":"He rushed out of the room.","id":"Dia bergegas keluar kamar."},{"jp":"授業が始まる前に宿題を出してください。","romaji":"Jugyou ga hajimaru mae ni shukudai wo dashite kudasai.","en":"Submit your homework before class starts.","id":"Kirimkan pekerjaan rumah Anda sebelum kelas dimulai."},{"jp":"彼女は歌い出しました。","romaji":"Kanojo wa utaidashimashita.","en":"She began to sing.","id":"Dia mulai bernyanyi."}]},{"pattern":"Verb 方 (〜hou)","meaning":"Indicates the way or method of doing something; often read as '～かた' ('how to', 'the way of').","meaningId":"Menunjukkan cara atau metode melakukan sesuatu; sering dibaca sebagai '～かた' ('cara', 'cara').","formation":"Verb-stem + 方 (read as かた)","formationId":"Kata kerja dasar + 方 (dibaca かた)","examples":[{"jp":"誰かがケーキの作り方を知っていますか？","romaji":"Dareka ga keeki no tsukurikata o shitteimasu ka?","en":"Does anyone know how to make a cake?","id":"Ada yang tau cara buat kuenya?"},{"jp":"彼女は英語の話し方を学んでいます。","romaji":"Kanojo wa eigo no hanashikata o manandeimasu.","en":"She is learning how to speak English.","id":"Dia sedang belajar bagaimana berbicara bahasa Inggris."},{"jp":"このパソコンの使い方を教えてください。","romaji":"Kono pasokon no tsukaikata o oshiete kudasai.","en":"Please teach me how to use this computer.","id":"Tolong ajari saya cara menggunakan komputer ini."},{"jp":"数学の問題の解き方を覚えるのが難しいです。","romaji":"Suugaku no mondai no tokikata o oboeru no ga muzukashii desu.","en":"It is difficult to remember the way to solve math problems.","id":"Sulit mengingat cara menyelesaikan soal matematika."}]},{"pattern":"Verb 終わる (〜owaru)","meaning":"Verbal action is completed; 'to finish', 'to end'.","meaningId":"Tindakan verbal selesai; 'untuk menyelesaikan', 'untuk mengakhiri'.","formation":"終わる (owaru) is a godan (u-verb)","formationId":"終わる (owaru) adalah godan (kata kerja-u)","examples":[{"jp":"映画が終わったら、家に帰ります。","romaji":"Eiga ga owattara, ie ni kaerimasu.","en":"When the movie finishes, I'll go home.","id":"Kalau filmnya sudah selesai, aku akan pulang."},{"jp":"仕事が終わるまで、待ってください。","romaji":"Shigoto ga owaru made, matte kudasai.","en":"Please wait until the work is finished.","id":"Mohon tunggu hingga pekerjaan selesai."},{"jp":"パーティーはもうすぐ終わります。","romaji":"Paatii wa mou sugu owarimasu.","en":"The party will be over soon.","id":"Pestanya akan segera berakhir."},{"jp":"試験が終わったら、友達と遊びに行く予定です。","romaji":"Shiken ga owattara, tomodachi to asobi ni iku yotei desu.","en":"Once the exam is over, I plan to go out with my friends.","id":"Setelah ujian selesai, aku berencana untuk pergi keluar bersama teman-temanku."}]},{"pattern":"Verb + 続ける (つづける, tsuzukeru)","meaning":"To continue doing or to keep doing an action.","meaningId":"Untuk terus melakukan atau terus melakukan suatu tindakan.","formation":"Verb-masu-stem + 続ける","formationId":"Kata kerja-masu-batang + 続ける","examples":[{"jp":"彼は毎日ジムで運動を続けています。","romaji":"Kare wa mainichi jimu de undou o tsuzuketeimasu.","en":"He continues to exercise at the gym every day.","id":"Dia terus berolahraga di gym setiap hari."},{"jp":"彼女は勉強を続けるために図書館に行きました。","romaji":"Kanojo wa benkyou o tsuzukeru tame ni toshokan ni ikimashita.","en":"She went to the library to continue studying.","id":"Dia pergi ke perpustakaan untuk melanjutkan belajar."},{"jp":"私たちは雨にも関わらず散歩を続けました。","romaji":"Watashitachi wa ame ni mo kakawarazu sanpo o tsuzukemashita.","en":"We continued walking despite the rain.","id":"Kami terus berjalan meski hujan."},{"jp":"彼は仕事を続けることに決めた。","romaji":"Kare wa shigoto o tsuzukeru koto ni kimeta.","en":"He decided to continue working.","id":"Dia memutuskan untuk terus bekerja."}]},{"pattern":"～かしら (〜kashira)","meaning":"Indicates uncertainty or doubt; 'I wonder', 'I'm not sure'.","meaningId":"Menunjukkan ketidakpastian atau keraguan; 'Saya bertanya-tanya', 'Saya tidak yakin'.","formation":"Verb-casual + かしら, い-Adjective + かしら, な-Adjective + かしら, Noun + かしら","formationId":"Kata Kerja-kasual + かしら, い-Kata Sifat + かしら, な-Kata Sifat + かしら, Kata Benda + かしら","examples":[{"jp":"今日は雨が降るかしら？","romaji":"Kyou wa ame ga furu kashira?","en":"I wonder if it will rain today?","id":"Aku ingin tahu apakah hari ini akan hujan?"},{"jp":"このケーキは美味しいかしら？","romaji":"Kono keeki wa oishii kashira?","en":"I wonder if this cake is delicious?","id":"Aku ingin tahu apakah kue ini enak?"},{"jp":"彼は病気かしら？","romaji":"Kare wa byouki kashira?","en":"I wonder if he is sick?","id":"Aku ingin tahu apakah dia sakit?"},{"jp":"彼女は学生かしら？","romaji":"Kanojo wa gakusei kashira?","en":"I wonder if she is a student?","id":"Aku ingin tahu apakah dia seorang pelajar?"}]},{"pattern":"～かどうか (〜ka dou ka)","meaning":"Used to express 'whether' or 'if' in indirect questions or statements.","meaningId":"Digunakan untuk menyatakan 'apakah' atau 'jika' dalam pertanyaan atau pernyataan tidak langsung.","formation":"Verb-casual + かどうか, い-Adjective + かどうか, な-Adjective + (だ)かどうか, Noun + (だ)かどうか","formationId":"Kata Kerja-kasual + かどうか, い-Kata Sifat + かどうか, な-Kata Sifat + (だ)かどうか, Kata Benda + (だ)かどうか","examples":[{"jp":"彼が来るかどうか知りません。","romaji":"Kare ga kuru ka dou ka shirimasen.","en":"I don't know if he will come or not.","id":"Saya tidak tahu apakah dia akan datang atau tidak."},{"jp":"この本が面白いかどうか教えてください。","romaji":"Kono hon ga omoshiroi ka dou ka oshiete kudasai.","en":"Please tell me if this book is interesting or not.","id":"Tolong beri tahu saya apakah buku ini menarik atau tidak."},{"jp":"彼女が綺麗だかどうかは分かりません。","romaji":"Kanojo ga kirei da ka dou ka wa wakarimasen.","en":"I don't know whether she is beautiful or not.","id":"Saya tidak tahu apakah dia cantik atau tidak."},{"jp":"彼が先生だかどうか覚えていません。","romaji":"Kare ga sensei da ka dou ka oboete imasen.","en":"I don't remember if he is a teacher or not.","id":"Saya tidak ingat apakah dia seorang guru atau bukan."}]},{"pattern":"～かなあ (〜kanaa)","meaning":"Expresses uncertainty or wonder; 'I wonder', 'I'm not sure'.","meaningId":"Mengekspresikan ketidakpastian atau keheranan; 'Saya bertanya-tanya', 'Saya tidak yakin'.","formation":"Verb-casual + かなあ, い-Adjective + かなあ, (な-Adjective/Noun) + (だ) + かなあ","formationId":"Kata Kerja-kasual + かなあ, い-Kata Sifat + かなあ, (な-Kata Sifat/Kata Benda) + (だ) + かなあ","examples":[{"jp":"明日雨が降るかなあ。","romaji":"Ashita ame ga furu kanaa.","en":"I wonder if it will rain tomorrow.","id":"Aku ingin tahu apakah besok akan turun hujan."},{"jp":"このケーキは美味しいかなあ。","romaji":"Kono keeki wa oishii kanaa.","en":"I wonder if this cake is delicious.","id":"Aku ingin tahu apakah kue ini enak."},{"jp":"彼は病気かなあ。","romaji":"Kare wa byouki kanaa.","en":"I wonder if he is sick.","id":"Aku ingin tahu apakah dia sakit."},{"jp":"彼女は学生かなあ。","romaji":"Kanojo wa gakusei kanaa.","en":"I wonder if she is a student.","id":"Aku ingin tahu apakah dia seorang pelajar."}]},{"pattern":"～かもしれない (〜kamoshirenai)","meaning":"Express uncertainty; 'maybe', 'might', 'possibly'.","meaningId":"Ekspresikan ketidakpastian; 'mungkin', 'mungkin', 'mungkin'.","formation":"Verb-casual + かもしれない, い-Adjective + かもしれない, な-Adjective + だかもしれない, Noun + だかもしれない","formationId":"Kata Kerja-kasual + かもしれない, い-Kata Sifat + かもしれない, な-Kata Sifat + だかもしれない, Kata Benda + だかもしれない","examples":[{"jp":"明日雨が降るかもしれない。","romaji":"Ashita ame ga furu kamoshirenai.","en":"It might rain tomorrow.","id":"Mungkin besok akan turun hujan."},{"jp":"このケーキは美味しいかもしれない。","romaji":"Kono keeki wa oishii kamoshirenai.","en":"This cake might be delicious.","id":"Kue ini mungkin enak."},{"jp":"彼が病気かもしれない。","romaji":"Kare ga byouki kamoshirenai.","en":"He might be sick.","id":"Dia mungkin sakit."},{"jp":"彼女は学生かもしれない。","romaji":"Kanojo wa gakusei kamoshirenai.","en":"She might be a student.","id":"Dia mungkin seorang pelajar."}]},{"pattern":"～から (〜kara)","meaning":"Express a reason or cause; 'because', 'since', 'due to'.","meaningId":"Nyatakan alasan atau sebab; 'karena', 'sejak', 'karena'.","formation":"Verb-casual + から, い-Adjective + から, な-Adjective + だから, Noun + だから","formationId":"Kata Kerja-kasual + から, い-Kata Sifat + から, な-Kata Sifat + だから, Kata Benda + だから","examples":[{"jp":"雨が降るから、傘を持って行ってください。","romaji":"Ame ga furu kara, kasa wo motte itte kudasai.","en":"Because it's raining, please bring an umbrella.","id":"Karena hujan, harap membawa payung."},{"jp":"このケーキは美味しいから、みんな食べるでしょう。","romaji":"Kono keeki wa oishii kara, minna taberu deshou.","en":"Because this cake is delicious, everyone will probably eat it.","id":"Karena kue ini enak, semua orang mungkin akan memakannya."},{"jp":"彼は病気だから、学校を休みます。","romaji":"Kare wa byouki dakara, gakkou wo yasumimasu.","en":"He will be absent from school because he is sick.","id":"Dia akan bolos sekolah karena sakit."},{"jp":"今日は日曜日だから、学校がありません。","romaji":"Kyou wa nichiyoubi dakara, gakkou ga arimasen.","en":"There is no school today because it is Sunday.","id":"Tidak ada sekolah hari ini karena ini hari Minggu."}]},{"pattern":"～けれど (〜keredo)","meaning":"Indicate a soft contrast or contradiction; 'but', 'however'.","meaningId":"Tunjukkan kontras atau kontradiksi yang lembut; 'tapi', 'namun'.","formation":"Verb-casual + けれど, い-Adjective + けれど, な-Adjective + だけれど, Noun + だけれど","formationId":"Kata Kerja-kasual + けれど, い-Kata Sifat + けれど, な-Kata Sifat + だけれど, Kata Benda + だけれど","examples":[{"jp":"今日は忙しいけれど、明日はもっと時間がある。","romaji":"Kyou wa isogashii keredo, ashita wa motto jikan ga aru.","en":"I'm busy today, but I have more time tomorrow.","id":"Saya sibuk hari ini, tetapi saya punya lebih banyak waktu besok."},{"jp":"このレストランは高いけれど、料理が美味しい。","romaji":"Kono resutoran wa takai keredo, ryouri ga oishii.","en":"This restaurant is expensive, but the food is delicious.","id":"Restoran ini mahal, tapi makanannya enak."},{"jp":"彼は若いけれど、とても経験豊富だ。","romaji":"Kare wa wakai keredo, totemo keiken houfu da.","en":"He is young, but he is very experienced.","id":"Dia masih muda, tapi dia sangat berpengalaman."},{"jp":"彼女は病気だけれど、明るく元気だ。","romaji":"Kanojo wa byouki da keredo, akaruku genki da.","en":"She is sick, but she is cheerful and energetic.","id":"Dia sakit, tapi dia ceria dan energik."}]},{"pattern":"～させてください (〜sasete kudasai)","meaning":"Express a polite request to allow or permit someone to do something.","meaningId":"Menyatakan permintaan sopan untuk memperbolehkan atau mengijinkan seseorang melakukan sesuatu.","formation":"Verb-causative form + ください","formationId":"Bentuk kata kerja kausatif + ください","examples":[{"jp":"もう少し考えさせてください。","romaji":"Mou sukoshi kangaesasete kudasai.","en":"Please let me think a little more.","id":"Tolong izinkan saya berpikir lebih jauh."},{"jp":"写真を撮らせてください。","romaji":"Shashin o torasete kudasai.","en":"Please let me take a photo.","id":"Tolong izinkan saya mengambil foto."},{"jp":"もうちょっと練習させてください。","romaji":"Mou chotto renshuu sasete kudasai.","en":"Please let me practice a little more.","id":"Tolong izinkan saya berlatih sedikit lagi."},{"jp":"ここで待たせてください。","romaji":"Koko de matasete kudasai.","en":"Please let me wait here.","id":"Tolong biarkan aku menunggu di sini."}]},{"pattern":"～し、～し、～ (〜shi, 〜shi, 〜)","meaning":"Express multiple reasons or characteristics; 'and', 'because', 'since'.","meaningId":"Ekspresikan berbagai alasan atau karakteristik; 'dan', 'karena', 'sejak'.","formation":"Verb-casual + し, い-Adjective + し, な-Adjective + だし, Noun + だし","formationId":"Kata kerja-kasual + し, い-Kata Sifat + し, な-Kata Sifat + だし, Kata Benda + だし","examples":[{"jp":"彼は若いし、元気だし、フレンドリーだし、みんなと仲良くなれると思います。","romaji":"Kare wa wakai shi, genki da shi, furendorī da shi, minna to nakayoku nareru to omoimasu.","en":"He is young, energetic, friendly, and I think he can get along with everyone.","id":"Dia muda, energik, ramah, dan menurutku dia bisa bergaul dengan semua orang."},{"jp":"このレストランは料理が美味しいし、雰囲気がいいし、価格も手頃だからお勧めです。","romaji":"Kono resutoran wa ryouri ga oishii shi, fun'iki ga ii shi, kakaku mo tegoro dakara osusume desu.","en":"I recommend this restaurant because the food is delicious, the atmosphere is nice, and the prices are reasonable.","id":"Saya merekomendasikan restoran ini karena makanannya enak, suasananya enak, dan harganya masuk akal."},{"jp":"彼女は勉強ができるし、スポーツも得意だし、性格もいい。","romaji":"Kanojo wa benkyou ga dekiru shi, supōtsu mo tokui da shi, seikaku mo ii.","en":"She is good at studying, good at sports, and has a good personality.","id":"Dia pandai belajar, pandai olahraga, dan memiliki kepribadian yang baik."},{"jp":"今日は寒いし、雨も降っているし、家でゆっくり休んだ方がいいでしょう。","romaji":"Kyou wa samui shi, ame mo futte iru shi, ie de yukkuri yasunda hou ga ii deshou.","en":"It's cold today, and it's raining, so it's better to relax at home.","id":"Hari ini dingin dan hujan, jadi lebih baik bersantai di rumah."}]},{"pattern":"～すぎる (〜sugiru)","meaning":"Expresses that something is excessive or overdone; 'too much', 'too', 'over'.","meaningId":"Menyatakan bahwa ada sesuatu yang berlebihan atau berlebihan; 'terlalu banyak', 'terlalu', 'berakhir'.","formation":"Verb-stem + すぎる, い-Adjective (remove い) + すぎる, な-Adjective + すぎる","formationId":"Kata kerja dasar + すぎる, い-Kata Sifat (hapus い) + すぎる, な-Kata Sifat + すぎる","examples":[{"jp":"この部屋は暑すぎる。","romaji":"Kono heya wa atsui sugiru.","en":"This room is too hot.","id":"Ruangan ini terlalu panas."},{"jp":"彼は早く来すぎた。","romaji":"Kare wa hayaku kisugita.","en":"He came too early.","id":"Dia datang terlalu dini."},{"jp":"この箱は重すぎて持ち上げられない。","romaji":"Kono hako wa omosugite mochiagerarenai.","en":"This box is too heavy to lift.","id":"Kotak ini terlalu berat untuk diangkat."},{"jp":"彼女は忙しくて遊びすぎはしない。","romaji":"Kanojo wa isogashikute asobisugi wa shinai.","en":"She's too busy to play too much.","id":"Dia terlalu sibuk untuk bermain terlalu banyak."}]},{"pattern":"～ずつ (〜zutsu)","meaning":"Indicates equal distribution; 'each', 'per', 'apiece'.","meaningId":"Menunjukkan pemerataan; 'masing-masing', 'per', 'masing-masing'.","formation":"Noun + ずつ","formationId":"Kata benda + ずつ","examples":[{"jp":"りんごを2つずつ配ります。","romaji":"Ringo wo futatsu zutsu kubarimasu.","en":"I will distribute 2 apples each.","id":"Saya akan membagikan masing-masing 2 apel."},{"jp":"私たちは週に一度ずつ掃除をします。","romaji":"Watashitachi wa shuu ni ichido zutsu souji o shimasu.","en":"We each clean once per week.","id":"Kami masing-masing membersihkannya seminggu sekali."},{"jp":"みんなは同じ距離を一歩ずつ歩いた。","romaji":"Minna wa onaji kyori o ippo zutsu aruita.","en":"Everyone walked the same distance, one step at a time.","id":"Setiap orang berjalan dalam jarak yang sama, selangkah demi selangkah."},{"jp":"彼女は子供たちに一枚ずつプレゼントをくれました。","romaji":"Kanojo wa kodomotachi ni ichimai zutsu purezento o kuremashita.","en":"She gave one present to each child.","id":"Dia memberikan satu hadiah untuk setiap anak."}]},{"pattern":"～そうだ (〜sou da)","meaning":"Express the appearance, seeming, or feeling of something; 'looks like', 'seems', 'appears'.","meaningId":"Mengekspresikan penampilan, kesan, atau perasaan sesuatu; 'sepertinya', 'tampaknya', 'tampak'.","formation":"Verb-ますstem + そうだ, い-Adjective (without い) + そうだ, な-Adjective + そうだ","formationId":"Kata Kerja-ますbatang + そうだ, い-Kata Sifat (tanpa い) + そうだ, な-Kata Sifat + そうだ","examples":[{"jp":"その花はとてもきれいそうだ。","romaji":"Sono hana wa totemo kirei sou da.","en":"That flower looks very beautiful.","id":"Bunga itu terlihat sangat indah."},{"jp":"彼は疲れそうだ。","romaji":"Kare wa tsukare sou da.","en":"He looks tired.","id":"Dia terlihat lelah."},{"jp":"この本は面白そうだ。","romaji":"Kono hon wa omoshiro sou da.","en":"This book looks interesting.","id":"Buku ini terlihat menarik."},{"jp":"雨が降りそうだ。","romaji":"Ame ga furi sou da.","en":"It looks like it's going to rain.","id":"Sepertinya akan turun hujan."}]},{"pattern":"そんな (sonna) + Noun","meaning":"Expresses 'that kind/type of'; referring to something near the listener or previously mentioned.","meaningId":"Menyatakan 'jenis/tipe itu'; mengacu pada sesuatu yang dekat dengan pendengar atau disebutkan sebelumnya.","formation":"そんな + Noun","formationId":"そんな + Kata Benda","examples":[{"jp":"そんな話、信じられない。","romaji":"Sonna hanashi, shinjirarenai.","en":"I can't believe that kind of story.","id":"Aku tidak percaya cerita seperti itu."},{"jp":"そんな映画、見たくない。","romaji":"Sonna eiga, mitakunai.","en":"I don't want to watch that kind of movie.","id":"Saya tidak ingin menonton film seperti itu."}]},{"pattern":"そんなに～ (sonna ni〜)","meaning":"Expresses 'not so much', 'not that', or 'not so ~'.","meaningId":"Menyatakan 'tidak begitu banyak', 'tidak begitu', atau 'tidak terlalu ~'.","formation":"そんなに + Verb-negation, そんなに + Adjective-negation","formationId":"そんなに + Kata kerja-negasi, そんなに + Kata sifat-negasi","examples":[{"jp":"そんなに急がなくてもいいですよ。","romaji":"Sonna ni isoganakutemo ii desu yo.","en":"You don't have to hurry that much.","id":"Anda tidak perlu terburu-buru."},{"jp":"そんなに難しくない問題だと思います。","romaji":"Sonna ni muzukashikunai mondai da to omoimasu.","en":"I don't think the problem is that difficult.","id":"Menurutku masalahnya tidak terlalu sulit."},{"jp":"彼女はそんなに背が高くありません。","romaji":"Kanojo wa sonna ni se ga takaku arimasen.","en":"She is not that tall.","id":"Dia tidak setinggi itu."},{"jp":"そんなにたくさん食べる必要はないと思う。","romaji":"Sonna ni takusan taberu hitsuyou wa nai to omou.","en":"I don't think there's a need to eat so much.","id":"Menurutku, tidak perlu makan terlalu banyak."}]},{"pattern":"～たらいい (〜tara ii)","meaning":"Expressing a desire or suggestion for a particular outcome; 'it would be good if', 'should', 'I hope'.","meaningId":"Mengekspresikan keinginan atau saran untuk hasil tertentu; 'akan lebih baik jika', 'seharusnya', 'Saya harap'.","formation":"Verb-casual-past + たらいい","formationId":"Kata kerja-santai-masa lalu + たらいい","examples":[{"jp":"もっと勉強したらいいですよ。","romaji":"Motto benkyou shitara ii desu yo.","en":"It would be good if you studied more.","id":"Akan lebih baik jika Anda belajar lebih banyak."},{"jp":"雨が止んだらいいな。","romaji":"Ame ga yandara ii na.","en":"I hope the rain stops.","id":"Kuharap hujannya berhenti."},{"jp":"早く元気になったらいいですね。","romaji":"Hayaku genki ni nattara ii desu ne.","en":"It would be good if you got well soon.","id":"Alangkah baiknya jika Anda segera sembuh."},{"jp":"彼に連絡したらいいと思います。","romaji":"Kare ni renraku shitara ii to omoimasu.","en":"I think it would be good if you contacted him.","id":"Saya pikir akan lebih baik jika Anda menghubunginya."}]},{"pattern":"～たら いかがですか (〜tara ikaga desu ka)","meaning":"Making polite suggestions; 'how about if', 'what if', 'it would be good if'.","meaningId":"Memberikan saran yang sopan; 'bagaimana jika', 'bagaimana jika', 'akan lebih baik jika'.","formation":"Verb-casual, past + たら いかがですか, い-Adjective + かったら いかがですか, な-Adjective + だったら いかがですか, Noun + だったら いかがですか","formationId":"Kata kerja-kasual, lampau + たら いかがですか, い-Kata Sifat + かったら いかがですか, な-Kata Sifat + だったらいかがですか, Kata Benda + だったら いかがですか","examples":[{"jp":"図書館に行ったらいかがですか。","romaji":"Toshokan ni ittara ikaga desu ka.","en":"How about going to the library?","id":"Bagaimana kalau pergi ke perpustakaan?"},{"jp":"寒かったらカーディガンを着るのはいかがですか。","romaji":"Samukattara kaadigan wo kiru no wa ikaga desu ka.","en":"How about wearing a cardigan if it's cold?","id":"Bagaimana kalau memakai kardigan jika cuaca dingin?"},{"jp":"部屋が暗かったら照明を付けるのはいかがですか。","romaji":"Heya ga kurakattara shoumei wo tsukeru no wa ikaga desu ka.","en":"What if you turn on the light if the room is dark?","id":"Bagaimana jika Anda menyalakan lampu jika ruangan gelap?"},{"jp":"自分の意見だったら他人に聞くのはいかがですか。","romaji":"Jibun no iken dattara tanin ni kiku no wa ikaga desu ka.","en":"How about asking others if it's your own opinion?","id":"Bagaimana kalau bertanya kepada orang lain apakah itu pendapat Anda sendiri?"}]},{"pattern":"～たら どうですか (〜tara doudesuka)","meaning":"Express a suggestion or advice; 'what if', 'how about', 'why don't you'.","meaningId":"Menyampaikan saran atau nasehat; 'bagaimana kalau', 'bagaimana kalau', 'kenapa tidak'.","formation":"Verb-た form + ら どうですか","formationId":"Bentuk kata kerja-た + ら どうですか","examples":[{"jp":"スキーに行ったらどうですか？","romaji":"Sukii ni ittara doudesuka?","en":"How about going skiing?","id":"Bagaimana kalau bermain ski?"},{"jp":"少し休んだらどうですか？","romaji":"Sukoshi yasundara doudesuka?","en":"What if you take a little break?","id":"Bagaimana jika Anda istirahat sebentar?"},{"jp":"この本を読んだらどうですか？","romaji":"Kono hon wo yondara doudesuka?","en":"Why don't you read this book?","id":"Mengapa Anda tidak membaca buku ini?"},{"jp":"タクシーで帰ったらどうですか？","romaji":"Takushii de kaettara doudesuka?","en":"How about going home by taxi?","id":"Bagaimana kalau pulang naik taksi?"}]},{"pattern":"～たり～たり (〜tari 〜tari)","meaning":"Used to list multiple actions or states; 'doing things like', 'and so on', 'etc.'","meaningId":"Digunakan untuk mencantumkan beberapa tindakan atau status; 'melakukan hal-hal seperti', 'dan seterusnya', 'dll.'","formation":"Verb-ta + り + next verb-ta + り, い-Adjective + かったり + next verb-ta + り, な-Adjective + だったり + next verb-ta + り, Noun + だったり + next verb-ta + り","formationId":"Kata kerja-ta + り + kata kerja-ta berikutnya + り, い-Kata Sifat + かったり + kata kerja-ta berikutnya + り, な-Kata Sifat + だったり + kata kerja berikutnya-ta + り, Kata Benda + だったり + kata kerja berikutnya-ta + り","examples":[{"jp":"週末は映画を観たり、本を読んだりする。","romaji":"Shuumatsu wa eiga wo mitari, hon wo yondari suru.","en":"On weekends, I do things like watching movies and reading books.","id":"Di akhir pekan, saya melakukan hal-hal seperti menonton film dan membaca buku."},{"jp":"彼女は料理が上手だったり、歌がうまかったりする。","romaji":"Kanojo wa ryouri ga jouzu dattari, uta ga umakattari suru.","en":"She is good at things like cooking and singing.","id":"Dia pandai dalam hal-hal seperti memasak dan menyanyi."},{"jp":"このリゾートではスキーをしたり、温泉に入ったりできる。","romaji":"Kono rizooto de wa sukii wo shitari, onsen ni haittari dekiru.","en":"At this resort, you can do things like skiing and going to hot springs.","id":"Di resor ini, Anda dapat melakukan hal-hal seperti bermain ski dan pergi ke sumber air panas."},{"jp":"この地域の天気は暑かったり、寒かったりする。","romaji":"Kono chiiki no tenki wa atsukattari, samukattari suru.","en":"The weather in this area can be hot or cold.","id":"Cuaca di kawasan ini bisa panas atau dingin."}]},{"pattern":"～だろう (〜darou)","meaning":"Express probability, likelihood or certainty; 'probably', 'maybe', 'I think'.","meaningId":"Nyatakan probabilitas, kemungkinan, atau kepastian; 'mungkin', 'mungkin', 'menurutku'.","formation":"Verb-casual + だろう, い-Adjective (drop い) + だろう, な-Adjective + だろう, Noun + だろう","formationId":"Kata Kerja-kasual + だろう, い-Kata Sifat (jatuhkan い) + だろう, な-Kata Sifat + だろう, Kata Benda + だろう","examples":[{"jp":"明日は晴れるだろう。","romaji":"Ashita wa hareru darou.","en":"It will probably be sunny tomorrow.","id":"Mungkin besok akan cerah."},{"jp":"彼は忙しいだろう。","romaji":"Kare wa isogashii darou.","en":"He is probably busy.","id":"Dia mungkin sedang sibuk."},{"jp":"この本は面白いだろう。","romaji":"Kono hon wa omoshiroi darou.","en":"This book is probably interesting.","id":"Buku ini mungkin menarik."},{"jp":"彼女は先生だろう。","romaji":"Kanojo wa sensei darou.","en":"She is probably a teacher.","id":"Dia mungkin seorang guru."}]},{"pattern":"～っていう (〜tte iu)","meaning":"Used to quote, define, or specify a noun.","meaningId":"Digunakan untuk mengutip, mendefinisikan, atau menentukan kata benda.","formation":"Noun/Adjective/Verb + っていう + Noun","formationId":"Kata Benda/Kata Sifat/Kata Kerja + っていう + Kata Benda","examples":[{"jp":"ピザっていう料理が大好きです。","romaji":"Piza tte iu ryouri ga daisuki desu.","en":"I love the dish called pizza.","id":"Saya suka hidangan yang disebut pizza."},{"jp":"彼っていう男性はすごく面白いです。","romaji":"Kare tte iu dansei wa sugoku omoshiroi desu.","en":"That man (called ‘kare’) is really interesting.","id":"Pria itu (disebut 'kare') sangat menarik."},{"jp":"この映画っていうのは本当に感動的だよ。","romaji":"Kono eiga tte iu no wa hontou ni kandouteki da yo.","en":"This movie, I mean, is really touching.","id":"Film ini, maksudku, sangat menyentuh."},{"jp":"彼女が言っているっていう店はここではない。","romaji":"Kanojo ga itte iru tte iu mise wa koko de wa nai.","en":"The store she's talking about, I mean, is not here.","id":"Toko yang dia bicarakan, maksudku, tidak ada di sini."}]},{"pattern":"～で (〜de)","meaning":"Indicates the means, method, or place.","meaningId":"Menunjukkan cara, metode, atau tempat.","formation":"Noun + ～で","formationId":"Kata benda + ～で","examples":[{"jp":"私は自転車で学校に行きます。","romaji":"Watashi wa jitensha de gakkou ni ikimasu.","en":"I go to school by bicycle.","id":"Saya pergi ke sekolah dengan sepeda."},{"jp":"彼は日本語で手紙を書いた。","romaji":"Kare wa nihongo de tegami wo kaita.","en":"He wrote a letter in Japanese.","id":"Dia menulis surat dalam bahasa Jepang."},{"jp":"鉛筆で絵を描きました。","romaji":"Enpitsu de e wo kakimashita.","en":"I drew a picture with a pencil.","id":"Saya menggambar dengan pensil."},{"jp":"レストランで昼食を食べました。","romaji":"Resutoran de chuushoku wo tabemashita.","en":"I had lunch at a restaurant.","id":"Saya makan siang di sebuah restoran."}]},{"pattern":"～でしょう (〜deshou)","meaning":"A conjecture or probability; 'probably', 'I think', 'it seems'.","meaningId":"Sebuah dugaan atau probabilitas; 'mungkin', 'menurutku', 'sepertinya'.","formation":"Verb-ますstem + でしょう, い-Adjective + でしょう, な-Adjective + でしょう, Noun + でしょう","formationId":"Kata Kerja-ますbatang + でしょう, い-Kata Sifat + でしょう, な-Kata Sifat + でしょう, Kata Benda + でしょう","examples":[{"jp":"明日は晴れでしょう。","romaji":"Ashita wa hare deshou.","en":"It will probably be sunny tomorrow.","id":"Mungkin besok akan cerah."},{"jp":"彼は元気でしょう。","romaji":"Kare wa genki deshou.","en":"He is probably fine.","id":"Dia mungkin baik-baik saja."},{"jp":"この本は面白いでしょう。","romaji":"Kono hon wa omoshiroi deshou.","en":"This book is probably interesting.","id":"Buku ini mungkin menarik."},{"jp":"彼女は医者でしょう。","romaji":"Kanojo wa isha deshou.","en":"She is probably a doctor.","id":"Dia mungkin seorang dokter."}]},{"pattern":"～てはいけない (〜te wa ikenai)","meaning":"Expresses prohibition; 'must not', 'cannot'.","meaningId":"Menyatakan larangan; 'tidak boleh', 'tidak bisa'.","formation":"Verb-て-form + はいけない","formationId":"Kata kerja-て-bentuk + はいけない","examples":[{"jp":"公園でたばこを吸ってはいけない。","romaji":"Kouen de tabako o sutte wa ikenai.","en":"You must not smoke in the park.","id":"Anda tidak boleh merokok di taman."},{"jp":"ここで写真を撮ってはいけない。","romaji":"Koko de shashin o totte wa ikenai.","en":"You cannot take pictures here.","id":"Anda tidak dapat mengambil gambar di sini."},{"jp":"図書館で大きな声を出してはいけない。","romaji":"Toshokan de ookina koe o dashite wa ikenai.","en":"You must not speak loudly in the library.","id":"Anda tidak boleh berbicara keras-keras di perpustakaan."},{"jp":"バスの中で立っている人に席を譲ってはいけない。(Note: Unusual in real life, but grammatically correct.)","romaji":"Basu no naka de tatteiru hito ni seki o yuzutte wa ikenai.","en":"You should not give up your seat to someone standing on the bus. (Note: Odd in actual social context, but valid grammar.)","id":"Anda tidak boleh menyerahkan tempat duduk Anda kepada seseorang yang berdiri di dalam bus. (Catatan: Aneh dalam konteks sosial sebenarnya, tetapi tata bahasanya valid.)"}]},{"pattern":"～てもいい (〜temo ii)","meaning":"To give or ask permission; 'it's okay to', 'may', 'can'.","meaningId":"Untuk memberi atau meminta izin; 'tidak apa-apa untuk', 'boleh', 'bisa'.","formation":"Verb-て form + もいい","formationId":"Bentuk kata kerja-て + もいい","examples":[{"jp":"ここで写真を撮ってもいいですか。","romaji":"Koko de shashin wo tottemo ii desu ka?","en":"Is it okay to take a photo here?","id":"Bolehkah mengambil foto di sini?"},{"jp":"このリンゴを食べてもいいですか。","romaji":"Kono ringo wo tabetemo ii desu ka.","en":"May I eat this apple?","id":"Bolehkah saya makan apel ini?"},{"jp":"試験が終わったら、帰ってもいいです。","romaji":"Shiken ga owattara, kaettemo ii desu.","en":"You can go home after the exam is over.","id":"Anda bisa pulang setelah ujian selesai."},{"jp":"今夜友達と遊んでもいい。","romaji":"Kon'ya tomodachi to asondemo ii.","en":"It's okay to play with friends tonight.","id":"Tidak apa-apa bermain dengan teman malam ini."}]},{"pattern":"～ても/でも (〜te mo/demo)","meaning":"Expresses 'even if' or 'even though'; used to convey contradiction or contrast.","meaningId":"Menyatakan 'meskipun' atau 'meskipun'; digunakan untuk menyampaikan kontradiksi atau kontras.","formation":"Verb-て-form + も, い-Adjective (-い) + くても, な-Adjective + でも, Noun + でも","formationId":"Bentuk-kata kerja + も, い-Kata Sifat (-い) + くても, な-Kata Sifat + でも, Kata Benda + でも","examples":[{"jp":"雨が降っても、学校に行きます。","romaji":"Ame ga futte mo, gakkou ni ikimasu.","en":"Even if it rains, I will go to school.","id":"Walaupun hujan, aku tetap berangkat sekolah."},{"jp":"この部屋が汚くても、掃除しないつもりです。","romaji":"Kono heya ga kitanakute mo, souji shinai tsumori desu.","en":"Even if this room is dirty, I don't intend to clean it.","id":"Sekalipun ruangan ini kotor, saya tidak berniat membersihkannya."},{"jp":"その映画が面白くなくても、見ます。","romaji":"Sono eiga ga omoshirokunakute mo, mimasu.","en":"Even if that movie is not interesting, I will watch it.","id":"Walaupun film itu tidak menarik, saya akan menontonnya."},{"jp":"彼女が病気でも、働きます。","romaji":"Kanojo ga byouki demo, hatarakimasu.","en":"Even if she is sick, she will work.","id":"Sekalipun dia sakit, dia akan bekerja."}]},{"pattern":"～といい (〜to ii)","meaning":"Express a wish or hope; 'I hope', 'it would be good if'.","meaningId":"Ekspresikan keinginan atau harapan; 'Saya harap', 'akan lebih baik jika'.","formation":"Verb-casual + といい, い-Adjective + といい, な-Adjective + だといい, Noun + だといい","formationId":"Kata Kerja-kasual + といい, い-Kata Sifat + といい, な-Kata Sifat + だといい, Kata Benda + だといい","examples":[{"jp":"明日晴れるといいね。","romaji":"Ashita hareru to ii ne.","en":"I hope it will be sunny tomorrow.","id":"Saya berharap besok akan cerah."},{"jp":"この試験に合格するといい。","romaji":"Kono shiken ni goukaku suru to ii.","en":"I hope to pass this exam.","id":"Saya berharap untuk lulus ujian ini."},{"jp":"彼が元気だといいな。","romaji":"Kare ga genki da to ii na.","en":"I hope he is doing well.","id":"Saya harap dia baik-baik saja."},{"jp":"そのレストランが美味しいといいですね。","romaji":"Sono resutoran ga oishii to ii desu ne.","en":"It would be nice if that restaurant is delicious.","id":"Alangkah baiknya jika restoran itu enak."}]},{"pattern":"～という (〜to iu) Noun","meaning":"Used to define or explain a noun more specifically.","meaningId":"Digunakan untuk mendefinisikan atau menjelaskan kata benda secara lebih spesifik.","formation":"Noun + という + Noun, な-Adjective + という + Noun, Adjectival Verb + という + Noun","formationId":"Kata Benda + という + Kata Benda, な-Kata Sifat + という + Kata Benda, Kata Kerja Kata Sifat + という + Kata Benda","examples":[{"jp":"彼は日本語が流暢なアメリカ人という人です。","romaji":"Kare wa nihongo ga ryuuchou na amerikajin to iu hito desu.","en":"He is an American who speaks fluent Japanese.","id":"Dia adalah orang Amerika yang fasih berbahasa Jepang."},{"jp":"昨日、美味しかったというケーキを食べました。","romaji":"Kinou, oishikatta to iu keeki wo tabemashita.","en":"Yesterday, I ate a cake that was said to be delicious.","id":"Kemarin saya makan kue yang katanya enak."},{"jp":"有名な歌手という彼女は、たくさんのファンがいます。","romaji":"Yuumei na kashu to iu kanojo wa, takusan no fan ga imasu.","en":"She, who is called a famous singer, has many fans.","id":"Ia yang disebut-sebut sebagai penyanyi terkenal ini memiliki banyak penggemar."},{"jp":"環境に優しいという製品が人気があります。","romaji":"Kankyou ni yasashii to iu seihin ga ninki ga arimasu.","en":"Products that are said to be environmentally friendly are popular.","id":"Produk yang dikatakan ramah lingkungan memang banyak digemari."}]},{"pattern":"どういう Noun","meaning":"Asking for clarification or more information about a noun; 'what kind of', 'what sort of'.","meaningId":"Meminta klarifikasi atau informasi lebih lanjut tentang suatu kata benda; 'jenis apa', 'jenis apa'.","formation":"どういう + Noun","formationId":"どういう + Kata Benda","examples":[{"jp":"どういう仕事をしていますか？","romaji":"Dou iu shigoto wo shite imasu ka?","en":"What kind of work do you do?","id":"Jenis pekerjaan apa yang Anda lakukan?"},{"jp":"どういう映画が好きですか？","romaji":"Dou iu eiga ga suki desu ka?","en":"What kind of movies do you like?","id":"Jenis film apa yang kamu suka?"},{"jp":"どういう服を着たいですか？","romaji":"Dou iu fuku wo kitai desu ka?","en":"What kind of clothes do you want to wear?","id":"Pakaian seperti apa yang ingin kamu kenakan?"},{"jp":"どういう理由で遅れましたか？","romaji":"Dou iu riyuu de okuremashita ka?","en":"What sort of reason caused you to be late?","id":"Alasan apa yang menyebabkan Anda terlambat?"}]},{"pattern":"～と思う (〜to omou)","meaning":"Express one's thoughts or opinions; 'I think', 'I believe'.","meaningId":"Mengungkapkan pikiran atau pendapat seseorang; 'Saya pikir', 'Saya percaya'.","formation":"Verb-casual + と思う, い-Adjective + と思う, な-Adjective + だと思う, Noun + だと思う","formationId":"Kata Kerja-kasual + と思う, い-Kata Sifat + と思う, な-Kata Sifat + だと思う, Kata Benda + だと思う","examples":[{"jp":"明日晴れると思います。","romaji":"Ashita hareru to omoimasu.","en":"I think it will be sunny tomorrow.","id":"Saya pikir besok akan cerah."},{"jp":"この映画は面白いと思う。","romaji":"Kono eiga wa omoshiroi to omou.","en":"I think this movie is interesting.","id":"Menurutku film ini menarik."},{"jp":"彼は親切だと思います。","romaji":"Kare wa shinsetsu da to omoimasu.","en":"I think he is kind.","id":"Menurutku dia baik."},{"jp":"鈴木さんは先生だと思う。","romaji":"Suzuki-san wa sensei da to omou.","en":"I think Suzuki-san is a teacher.","id":"Saya pikir Suzuki-san adalah seorang guru."}]},{"pattern":"～という (〜to iu)","meaning":"Used to quote, express hearsay or define something.","meaningId":"Digunakan untuk mengutip, mengungkapkan desas-desus atau mendefinisikan sesuatu.","formation":"Verb-casual + という, い-Adjective + という, な-Adjective + という, Noun + という","formationId":"Kata Kerja-kasual + という, い-Kata Sifat + という, な-Kata Sifat + という, Kata Benda + という","examples":[{"jp":"彼は「好きだ」と言った。","romaji":"Kare wa 'suki da' to itta.","en":"He said 'I like you'.","id":"Dia berkata 'Aku menyukaimu'."},{"jp":"その映画は面白いという評判があります。","romaji":"Sono eiga wa omoshiroi to iu hyouban ga arimasu.","en":"The movie has a reputation for being interesting.","id":"Film ini memiliki reputasi menarik."},{"jp":"日本には富士山という高い山があります。","romaji":"Nihon ni wa Fujisan to iu takai yama ga arimasu.","en":"In Japan, there is a tall mountain called Mount Fuji.","id":"Di Jepang, ada sebuah gunung tinggi bernama Gunung Fuji."},{"jp":"彼女は難しい仕事をしているという話です。","romaji":"Kanojo wa muzukashii shigoto o shiteiru to iu hanashi desu.","en":"I heard she is doing a difficult job.","id":"Saya mendengar dia melakukan pekerjaan yang sulit."}]},{"pattern":"～ないといけない (〜nai to ikenai)","meaning":"Express a necessity; 'must', 'have to', 'need to'.","meaningId":"Ekspresikan suatu kebutuhan; 'harus', 'harus', 'perlu'.","formation":"Verb-negative + といけない","formationId":"Kata kerja-negatif + といけない","examples":[{"jp":"明日試験があるから、今夜勉強しないといけない。","romaji":"Ashita shiken ga aru kara, kon'ya benkyou shinai to ikenai.","en":"I have an exam tomorrow, so I have to study tonight.","id":"Saya ada ujian besok, jadi saya harus belajar malam ini."},{"jp":"９時に出発しないといけない。","romaji":"Ku-ji ni shuppatsu shinai to ikenai.","en":"We must leave at 9 o'clock.","id":"Kita harus berangkat jam 9."},{"jp":"風邪をひかないように、手をよく洗わないといけない。","romaji":"Kaze o hikanai you ni, te o yoku arawanai to ikenai.","en":"To avoid catching a cold, we have to wash our hands well.","id":"Untuk menghindari masuk angin, kita harus mencuci tangan dengan baik."},{"jp":"この仕事は明日までに終わらないといけない。","romaji":"Kono shigoto wa ashita made ni owaranai to ikenai.","en":"This work must be finished by tomorrow.","id":"Pekerjaan ini harus selesai besok."}]},{"pattern":"～なきゃいけない (〜nakya ikenai)","meaning":"Express a necessity or obligation; 'must', 'have to'.","meaningId":"Menyatakan suatu keharusan atau kewajiban; 'harus', 'harus'.","formation":"Verb-casual (negative form without い) + なきゃいけない","formationId":"Kata kerja kasual (bentuk negatif tanpa い) + なきゃいけない","examples":[{"jp":"明日までに宿題を終わらなきゃいけない。","romaji":"Ashita made ni shukudai wo owaranakya ikenai.","en":"I have to finish my homework by tomorrow.","id":"Saya harus menyelesaikan pekerjaan rumah saya besok."},{"jp":"もうすぐ出かけるから、急いで準備しなきゃいけない。","romaji":"Mou sugu dekakeru kara, isoide junbi shinakya ikenai.","en":"We're leaving soon, so I have to hurry and get ready.","id":"Kami akan segera berangkat, jadi saya harus bergegas dan bersiap-siap."},{"jp":"このプロジェクトは来週提出しなきゃいけない。","romaji":"Kono purojekuto wa raishuu teishutsu shinakya ikenai.","en":"I must submit this project by next week.","id":"Saya harus menyerahkan proyek ini minggu depan."},{"jp":"電車に乗る前に、切符を買わなきゃいけない。","romaji":"Densha ni noru mae ni, kippu wo kawanakya ikenai.","en":"I have to buy a ticket before getting on the train.","id":"Saya harus membeli tiket sebelum naik kereta."}]},{"pattern":"～なくちゃいけない (〜naku cha ikenai)","meaning":"Express the obligation to do something; 'have to', 'must', 'need to'.","meaningId":"Menyatakan kewajiban untuk melakukan sesuatu; 'harus', 'harus', 'perlu'.","formation":"Verb-ない form (-ない ending is dropped) + なくちゃいけない","formationId":"Bentuk kata kerja-ない (akhiran -ない dihilangkan) + なくちゃいけない","examples":[{"jp":"仕事に行かなくちゃいけないので、早起きしなければなりません。","romaji":"Shigoto ni ikanakucha ikenai node, hayaoki shinakereba narimasen.","en":"I have to go to work, so I must wake up early.","id":"Saya harus pergi bekerja, jadi saya harus bangun pagi."},{"jp":"試験があるから、勉強しなくちゃいけません。","romaji":"Shiken ga aru kara, benkyou shinakucha ikemasen.","en":"I have a test, so I must study.","id":"Aku ada ujian, jadi aku harus belajar."},{"jp":"パスポートを更新しなくちゃいけないので、大使館に行かなければ。","romaji":"Pasupooto wo koushin shinakucha ikenai node, taishikan ni ikanakereba.","en":"I have to renew my passport, so I need to go to the embassy.","id":"Saya harus memperbarui paspor saya, jadi saya harus pergi ke kedutaan."},{"jp":"今日はお金を払わなくちゃいけないから、銀行に行かないと。","romaji":"Kyou wa okane wo harawanakucha ikenai kara, ginkou ni ikanaito.","en":"I have to pay money today, so I need to go to the bank.","id":"Saya harus membayar uang hari ini, jadi saya harus pergi ke bank."}]},{"pattern":"～なくてはいけない (〜nakute wa ikenai)","meaning":"Expresses the necessity or obligation; 'must', 'have to'.","meaningId":"Mengungkapkan kebutuhan atau kewajiban; 'harus', 'harus'.","formation":"Verb-negative form + なくてはいけない","formationId":"Bentuk kata kerja negatif + なくてはいけない","examples":[{"jp":"宿題をしなくてはいけない。","romaji":"Shukudai o shinakute wa ikenai.","en":"I have to do my homework.","id":"Saya harus mengerjakan pekerjaan rumah saya."},{"jp":"この手紙を明日までに出さなくてはいけない。","romaji":"Kono tegami o ashita made ni dasanakute wa ikenai.","en":"I must send this letter by tomorrow.","id":"Saya harus mengirimkan surat ini besok."},{"jp":"食べ物を無駄にしなくてはいけない。","romaji":"Tabemono o muda ni shinakute wa ikenai.","en":"We must not waste food.","id":"Kita tidak boleh menyia-nyiakan makanan."},{"jp":"早退したいが、授業が終わるまで待たなくてはいけない。","romaji":"Soutai shitai ga, jugyou ga owaru made matanakute wa ikenai.","en":"I want to leave early, but I have to wait until the class finishes.","id":"Saya ingin berangkat lebih awal, tetapi saya harus menunggu sampai kelas selesai."}]},{"pattern":"～なくてもいい (〜nakutemo ii)","meaning":"Expresses that something is not necessary to do; 'it's okay if not', 'don't have to'.","meaningId":"Menyatakan bahwa ada sesuatu yang tidak perlu dilakukan; 'tidak apa-apa kalau tidak', 'tidak perlu'.","formation":"Verb-ない-form + てもいい","formationId":"Bentuk kata kerja-ない + てもいい","examples":[{"jp":"コーヒーは飲まなくてもいいです。","romaji":"Koohii wa nomanakutemo ii desu.","en":"You don't have to drink the coffee.","id":"Anda tidak perlu minum kopinya."},{"jp":"宿題を今日しなくてもいいです。","romaji":"Shukudai wo kyou shinakutemo ii desu.","en":"It's okay if you don't do your homework today.","id":"Tidak apa-apa jika Anda tidak mengerjakan pekerjaan rumah Anda hari ini."},{"jp":"すぐに返事をしなくてもいいですよ。","romaji":"Sugu ni henji wo shinakutemo ii desu yo.","en":"You don't have to reply immediately.","id":"Anda tidak perlu langsung membalasnya."},{"jp":"全部食べなくてもいいですから、無理しないでください。","romaji":"Zenbu tabenakutemo ii desu kara, muri shinai de kudasai.","en":"You don't have to eat everything, so please don't force yourself.","id":"Anda tidak harus makan semuanya, jadi jangan memaksakan diri."}]},{"pattern":"～なければ ならない (〜nakereba naranai)","meaning":"Express obligation or necessity; 'must', 'have to', 'need to'.","meaningId":"Kewajiban atau kebutuhan yang jelas; 'harus', 'harus', 'perlu'.","formation":"Verb-ない form + なければ ならない","formationId":"Bentuk kata kerja-ない + なければ ならない","examples":[{"jp":"宿題をやらなければならない。","romaji":"Shukudai wo yaranakereba naranai.","en":"I have to do my homework.","id":"Saya harus mengerjakan pekerjaan rumah saya."},{"jp":"明日までにこの本を読まなければならない。","romaji":"Ashita made ni kono hon wo yomanakereba naranai.","en":"I have to read this book by tomorrow.","id":"Saya harus membaca buku ini besok."},{"jp":"授業に遅れないように、早く起きなければならない。","romaji":"Jugyou ni okurenai you ni, hayaku okinakereba naranai.","en":"I have to wake up early so I don't be late for class.","id":"Aku harus bangun pagi agar tidak terlambat masuk kelas."},{"jp":"旅行に行く前に切符を買わなければならない。","romaji":"Ryokou ni iku mae ni kippu wo kawanakereba naranai.","en":"I have to buy a ticket before going on a trip.","id":"Saya harus membeli tiket sebelum melakukan perjalanan."}]},{"pattern":"～に (〜ni)","meaning":"Indicates direction, destination, purpose, or time.","meaningId":"Menunjukkan arah, tujuan, tujuan, atau waktu.","formation":"Noun + に","formationId":"Kata benda + に","examples":[{"jp":"母は私にケーキを作りました。","romaji":"Haha wa watashi ni keiki wo tsukurimashita.","en":"My mother made a cake for me.","id":"Ibuku membuatkan kue untukku."},{"jp":"彼女は東京に引っ越しました。","romaji":"Kanojo wa Toukyou ni hikkoshimashita.","en":"She moved to Tokyo.","id":"Dia pindah ke Tokyo."},{"jp":"銀行にお金を預けます。","romaji":"Ginkou ni okane wo azukemasu.","en":"I deposit money in the bank.","id":"Saya menyimpan uang di bank."},{"jp":"私は７時に起きます。","romaji":"Watashi wa shichi ji ni okimasu.","en":"I wake up at 7 o'clock.","id":"Saya bangun jam 7."}]},{"pattern":"～ので (〜node)","meaning":"Express a reason or a cause for something; 'because', 'since', 'so'.","meaningId":"Mengungkapkan alasan atau sebab atas sesuatu; 'karena', 'sejak', 'jadi'.","formation":"Verb-casual + ので, い-Adjective + ので, な-Adjective + なので, Noun + なので","formationId":"Kata Kerja-kasual + ので, い-Kata Sifat + ので, な-Kata Sifat + なので, Kata Benda + なので","examples":[{"jp":"明日試験があるので、今晩勉強します。","romaji":"Ashita shiken ga aru node, konban benkyou shimasu.","en":"I will study tonight because there is a test tomorrow.","id":"Saya akan belajar malam ini karena besok ada ujian."},{"jp":"このドレスが高いので、買わないことにします。","romaji":"Kono doresu ga takai node, kawanai koto ni shimasu.","en":"I will not buy this dress because it is expensive.","id":"Saya tidak akan membeli gaun ini karena mahal."},{"jp":"田中さんは病気なので、今日は来ません。","romaji":"Tanaka-san wa byouki na node, kyou wa kimasen.","en":"Tanaka-san will not come today since he is sick.","id":"Tanaka-san tidak akan datang hari ini karena dia sakit."},{"jp":"雨が降っているので、外に出ない方がいいですよ。","romaji":"Ame ga futte iru node, soto ni denai hou ga ii desu yo.","en":"It is better not to go outside because it is raining.","id":"Sebaiknya jangan keluar rumah karena sedang hujan."}]},{"pattern":"～のです (〜no desu)","meaning":"Provides an explanation or gives background information; 'the fact is', 'the reason is', 'actually'.","meaningId":"Memberikan penjelasan atau memberikan informasi latar belakang; 'faktanya adalah', 'alasannya adalah', 'sebenarnya'.","formation":"Verb-casual + のです, い-Adjective + のです, な-Adjective + なのです, Noun + なのです","formationId":"Kata Kerja-kasual + のです, い-Kata Sifat + のです, な-Kata Sifat + なのです, Kata Benda + なのです","examples":[{"jp":"この本は難しいのです。","romaji":"Kono hon wa muzukashii no desu.","en":"This book is difficult, you see.","id":"Buku ini sulit, Anda tahu."},{"jp":"明日は忙しいのです。","romaji":"Ashita wa isogashii no desu.","en":"The fact is, I am busy tomorrow.","id":"Faktanya adalah, saya sibuk besok."},{"jp":"彼女は英語の先生なのです。","romaji":"Kanojo wa eigo no sensei na no desu.","en":"The reason is, she is an English teacher.","id":"Pasalnya, dia adalah seorang guru bahasa Inggris."},{"jp":"私は風邪なのです。","romaji":"Watashi wa kaze na no desu.","en":"Actually, I’ve got a cold.","id":"Sebenarnya aku sedang flu."}]},{"pattern":"～のに (〜no ni)","meaning":"Used to express contrast between expectation and reality, or to indicate a purpose for doing something","meaningId":"Digunakan untuk mengungkapkan kontras antara harapan dan kenyataan, atau untuk menunjukkan tujuan melakukan sesuatu","formation":"Verb-casual + のに, い-Adjective + のに, な-Adjective + なのに, Noun + なのに","formationId":"Kata Kerja-kasual + のに, い-Kata Sifat + のに, な-Kata Sifat + なのに, Kata Benda + なのに","examples":[{"jp":"遅刻したのに、先生は怒らなかった。","romaji":"Chikoku shita no ni, sensei wa okoranakatta.","en":"Even though I was late, the teacher didn't get angry.","id":"Walaupun saya terlambat, guru tidak marah."},{"jp":"彼は疲れているのに、まだ働いています。","romaji":"Kare wa tsukarete iru no ni, mada hataraite imasu.","en":"Despite being tired, he is still working.","id":"Meski lelah, dia tetap bekerja."},{"jp":"勉強するのに静かな場所が必要です。","romaji":"Benkyou suru no ni, shizukana basho ga hitsuyou desu.","en":"In order to study, I need a quiet place.","id":"Untuk belajar, saya membutuhkan tempat yang tenang."},{"jp":"健康のために毎日運動するのに、うちでヨガをしている。","romaji":"Kenkou no tame ni mainichi undou suru no ni, uchi de yoga wo shite iru.","en":"In order to exercise for my health every day, I do yoga at home.","id":"Untuk berolahraga demi kesehatan saya setiap hari, saya melakukan yoga di rumah."}]},{"pattern":"～ばいい (〜ba ii)","meaning":"Express a suggestion or advice; 'should', 'it would be good if'.","meaningId":"Menyampaikan saran atau nasehat; 'seharusnya', 'akan lebih baik jika'.","formation":"Verb-ば-form + いい, い-Adjective + ければいい, な-Adjective + であればいい, Noun + であればいい","formationId":"Kata kerja-ば-bentuk + いい, い-Kata Sifat + ければいい, な-Kata Sifat + であればいい, Kata Benda + であればいい","examples":[{"jp":"もっと勉強すればいい。","romaji":"Motto benkyou sureba ii.","en":"You should study more.","id":"Anda harus belajar lebih banyak."},{"jp":"お腹が空いたら、何か食べればいい。","romaji":"Onaka ga suita ra, nanika tabereba ii.","en":"If you're hungry, you should eat something.","id":"Jika Anda lapar, Anda harus makan sesuatu."},{"jp":"もっと速く走ればいい。","romaji":"Motto hayaku hashireba ii.","en":"You should run faster.","id":"Anda harus berlari lebih cepat."},{"jp":"わからなければ、先生に聞けばいい。","romaji":"Wakaranakereba, sensei ni kikeba ii.","en":"If you don't understand, you should ask the teacher.","id":"Jika belum paham, sebaiknya tanyakan pada guru."}]},{"pattern":"～まで (〜made)","meaning":"Indicates extent, 'until', 'up to', 'as far as', 'even'.","meaningId":"Menunjukkan sejauh mana, 'sampai', 'sampai', 'sejauh', 'genap'.","formation":"Verb + まで, い-Adjective + まで, な-Adjective + まで, Noun + まで","formationId":"Kata Kerja + まで, い-Kata Sifat + まで, な-Kata Sifat + まで, Kata Benda + まで","examples":[{"jp":"仕事が終わるまで待っています。","romaji":"Shigoto ga owaru made matteimasu.","en":"I will wait until work is finished.","id":"Saya akan menunggu sampai pekerjaan selesai."},{"jp":"ここから駅まで歩いて10分かかります。","romaji":"Koko kara eki made aruite juppun kakarimasu.","en":"It takes 10 minutes to walk from here to the station.","id":"Dibutuhkan 10 menit berjalan kaki dari sini ke stasiun."},{"jp":"私は彼が成功するまで応援します。","romaji":"Watashi wa kare ga seikou suru made ouen shimasu.","en":"I will support him until he succeeds.","id":"Saya akan mendukungnya sampai dia berhasil."},{"jp":"彼女は猫まで好きです。","romaji":"Kanojo wa neko made suki desu.","en":"She likes even cats.","id":"Dia bahkan menyukai kucing."}]},{"pattern":"～までに (〜made ni)","meaning":"Express 'by' or 'before' a certain time or action.","meaningId":"Ekspresikan 'oleh' atau 'sebelum' waktu atau tindakan tertentu.","formation":"Verb-casual + までに, Noun + までに, Time expression + までに","formationId":"Kata kerja kasual + までに, Kata benda + までに, Ekspresi waktu + までに","examples":[{"jp":"明日の朝８時までに起きてください。","romaji":"Ashita no asa hachiji made ni okite kudasai.","en":"Please wake up by 8 a.m. tomorrow.","id":"Tolong bangun jam 8 pagi besok."},{"jp":"来週の金曜日までにレポートを提出してください。","romaji":"Raishuu no kinyoubi made ni repooto wo teishutsu shite kudasai.","en":"Please submit the report by next Friday.","id":"Silakan kirimkan laporannya paling lambat Jumat depan."},{"jp":"彼が帰るまでに料理を終わらせたい。","romaji":"Kare ga kaeru made ni ryouri wo owarasetai.","en":"I want to finish cooking before he comes back.","id":"Saya ingin menyelesaikan memasak sebelum dia kembali."},{"jp":"３０分までに駅に着く必要があります。","romaji":"Sanjuppun made ni eki ni tsuku hitsuyou ga arimasu.","en":"We need to arrive at the station by 30 minutes (from now).","id":"Kita harus tiba di stasiun dalam waktu 30 menit (dari sekarang)."}]},{"pattern":"～まま (〜mama)","meaning":"Express 'as it is', 'while' or 'unchanged state'.","meaningId":"Ekspresikan 'sebagaimana adanya', 'sementara' atau 'keadaan tidak berubah'.","formation":"Verb-てform + いる+ まま, Adjective (い & な) + まま, Noun + のまま","formationId":"Kata kerja-てform + いる+ まま, Kata Sifat (い & な) + まま, Kata Benda + のまま","examples":[{"jp":"ドアを開けたまま出かけてしまった。","romaji":"Doa o aketa mama dekakete shimatta.","en":"I accidentally left with the door open.","id":"Saya tidak sengaja pergi dengan pintu terbuka."},{"jp":"彼は目覚まし時計を止めたまま寝てしまった。","romaji":"Kare wa mezamashi dokei o tometa mama nete shimatta.","en":"He fell asleep with the alarm clock stopped.","id":"Dia tertidur dengan jam alarm berhenti."},{"jp":"その部屋はきれいなままにしておいてください。","romaji":"Sono heya wa kirei na mama ni shite oite kudasai.","en":"Please keep the room clean.","id":"Tolong jaga kebersihan ruangan."},{"jp":"彼女は子供のままの心を持っている。","romaji":"Kanojo wa kodomo no mama no kokoro o motte iru.","en":"She has the heart of a child.","id":"Dia memiliki hati seorang anak kecil."}]},{"pattern":"～みたいだ (〜mitai da)","meaning":"Indicates similarity, resemblance or 'like'; 'it seems', 'appears', 'looks like'.","meaningId":"Menunjukkan kesamaan, kemiripan atau 'suka'; 'sepertinya', 'tampaknya', 'sepertinya'.","formation":"Verb-casual + みたいだ, い-Adjective + みたいだ, な-Adjective + みたいだ, Noun + みたいだ","formationId":"Kata Kerja-kasual + みたいだ, い-Kata Sifat + みたいだ, な-Kata Sifat + みたいだ, Kata Benda + みたいだ","examples":[{"jp":"彼女が病気のみたいだ。","romaji":"Kanojo ga byouki no mitai da.","en":"She seems to be sick.","id":"Dia sepertinya sakit."},{"jp":"このドレスは高いみたいだ。","romaji":"Kono doresu wa takai mitai da.","en":"This dress seems to be expensive.","id":"Gaun ini sepertinya mahal."},{"jp":"あの人は有名人みたいだ。","romaji":"Ano hito wa yuumeijin mitai da.","en":"That person looks like a celebrity.","id":"Orang itu terlihat seperti selebriti."},{"jp":"彼は今忙しいみたいだ。","romaji":"Kare wa ima isogashii mitai da.","en":"It seems he is busy right now.","id":"Sepertinya dia sedang sibuk saat ini."}]},{"pattern":"～も (〜mo)","meaning":"Indicates 'also', 'too', or 'as well'.","meaningId":"Menunjukkan 'juga', 'terlalu', atau 'juga'.","formation":"Verb-casual + も, い-Adjective + も, な-Adjective + も, Noun + も","formationId":"Kata kerja-kasual + も, い-Kata Sifat + も, な-Kata Sifat + も, Kata Benda + も","examples":[{"jp":"私もお寿司が好きです。","romaji":"Watashi mo osushi ga suki desu.","en":"I also like sushi.","id":"Saya juga suka sushi."},{"jp":"彼女は英語も日本語も話せます。","romaji":"Kanojo wa eigo mo nihongo mo hanasemasu.","en":"She can speak both English and Japanese.","id":"Dia bisa berbicara bahasa Inggris dan Jepang."},{"jp":"その映画は面白いし、彼も見たいと言っています。","romaji":"Sono eiga wa omoshiroi shi, kare mo mitai to itteimasu.","en":"That movie is interesting, and he also said he wants to see it.","id":"Film itu menarik, dan dia juga bilang ingin menontonnya."},{"jp":"今日は寒いです。明日も寒いでしょう。","romaji":"Kyou wa samui desu. Ashita mo samui deshou.","en":"It is cold today. It will probably be cold tomorrow as well.","id":"Hari ini dingin. Mungkin besok juga akan dingin."}]},{"pattern":"～ようだ (〜you da)","meaning":"Expresses appearance, similarity or inference; 'it seems', 'it looks like', 'it appears'.","meaningId":"Mengekspresikan penampilan, kesamaan atau kesimpulan; 'sepertinya', 'sepertinya', 'tampaknya'.","formation":"Verb-て form + ようだ, い-Adjective (drop い) + ようだ, な-Adjective + のようだ, Noun + のようだ","formationId":"Bentuk kata kerja-て + ようだ, い-Kata Sifat (jatuhkan い) + ようだ, な-Kata Sifat + のようだ, Kata Benda + のようだ","examples":[{"jp":"彼は元気がないようだ。","romaji":"Kare wa genki ga nai you da.","en":"He seems to be lacking energy.","id":"Dia sepertinya kekurangan energi."},{"jp":"この料理は美味しいようだ。","romaji":"Kono ryouri wa oishii you da.","en":"This dish seems to be delicious.","id":"Hidangan ini sepertinya enak."},{"jp":"彼女は有名人のようだ。","romaji":"Kanojo wa yuumeijin no you da.","en":"She seems like a famous person.","id":"Dia tampak seperti orang terkenal."},{"jp":"この部屋は図書館のようだ。","romaji":"Kono heya wa toshokan no you da.","en":"This room looks like a library.","id":"Ruangan ini terlihat seperti perpustakaan."}]},{"pattern":"～んです (〜n desu)","meaning":"Provide an explanation or reason; 'it is that', 'the thing is', 'the reason is'.","meaningId":"Memberikan penjelasan atau alasan; 'itulah', 'masalahnya', 'alasannya'.","formation":"Verb-casual + んです, い-Adjective + んです, な-Adjective + なんです, Noun + なんです","formationId":"Kata Kerja-kasual + んです, い-Kata Sifat + んです, な-Kata Sifat + なんです, Kata Benda + なんです","examples":[{"jp":"遅れたんですが、電車が遅れました。","romaji":"Okuretan desuga, densha ga okuremashita.","en":"I was late because the train was delayed.","id":"Saya terlambat karena keretanya tertunda."},{"jp":"疲れたんです。","romaji":"Tsukareta n desu.","en":"I'm tired (that's why).","id":"Saya lelah (itulah alasannya)."},{"jp":"彼は優しいんです。","romaji":"Kare wa yasashii n desu.","en":"The thing is, he is kind.","id":"Masalahnya, dia baik hati."},{"jp":"宿題が多いんです。","romaji":"Shukudai ga ooi n desu.","en":"The reason is I have a lot of homework.","id":"Alasannya adalah saya mempunyai banyak pekerjaan rumah."}]},{"pattern":"文A。そのうえ 文B。","meaning":"Shows additional information; 'furthermore', 'besides', 'in addition'.","meaningId":"Menampilkan informasi tambahan; 'selanjutnya', 'selain', 'selain itu'.","formation":"Sentence A + そのうえ + Sentence B + 。","formationId":"Kalimat A + そのうえ + Kalimat B + 。","examples":[{"jp":"このソフトウェアは使いやすい。そのうえ、価格も手ごろだ。","romaji":"Kono sofutouea wa tsukaiyasui. Sono ue, kakaku mo tegoro da.","en":"This software is easy to use. Furthermore, the price is reasonable.","id":"Perangkat lunak ini mudah digunakan. Selain itu, harganya masuk akal."},{"jp":"彼女は美人だ。そのうえ、頭もいい。","romaji":"Kanojo wa bijin da. Sono ue, atama mo ii.","en":"She is beautiful. In addition, she is smart.","id":"Dia cantik. Selain itu, dia pintar."},{"jp":"この映画は面白い。そのうえ、俳優たちの演技も素晴らしい。","romaji":"Kono eiga wa omoshiroi. Sono ue, haiyuutachi no engi mo subarashii.","en":"This movie is interesting. Besides, the actors' performances are also great.","id":"Film ini menarik. Selain itu, penampilan para aktornya juga bagus."},{"jp":"東京はたくさんの観光スポットがある。そのうえ、美味しいレストランも多い。","romaji":"Toukyou wa takusan no kankou supotto ga aru. Sono ue, oishii resutoran mo oi.","en":"Tokyo has many sightseeing spots. In addition, there are many delicious restaurants.","id":"Tokyo memiliki banyak tempat wisata. Selain itu, ada banyak restoran enak."}]},{"pattern":"文A。それで 文B (Bun A. Sorede Bun B)","meaning":"Used to connect two sentences; 'So', 'That's why', 'Therefore'.","meaningId":"Digunakan untuk menghubungkan dua kalimat; 'Jadi', 'Itulah sebabnya', 'Oleh karena itu'.","formation":"Sentence A。それで Sentence B。","formationId":"Kalimat A. Kalimat B.","examples":[{"jp":"今日は暑いです。それで、エアコンをつけました。","romaji":"Kyou wa atsui desu. Sorede, eakon wo tsukemashita.","en":"It is hot today. So, I turned on the air conditioner.","id":"Hari ini panas. Jadi, saya menyalakan AC."},{"jp":"電車が遅れました。それで、仕事に遅れてしまいました。","romaji":"Densha ga okuremashita. Sorede, shigoto ni okurete shimaimashita.","en":"The train was delayed. That's why I was late for work.","id":"Keretanya tertunda. Itu sebabnya aku terlambat ke kantor."},{"jp":"彼は疲れている。それで、早く寝ることにした。","romaji":"Kare wa tsukarete iru. Sorede, hayaku neru koto ni shita.","en":"He is tired. Therefore, he decided to go to bed early.","id":"Dia lelah. Karena itu, ia memutuskan untuk tidur lebih awal."},{"jp":"試験に合格しました。それで、友達とお祝いパーティーを開きました。","romaji":"Shiken ni goukaku shimashita. Sorede, tomodachi to oiwai paatii wo hirakimashita.","en":"I passed the exam. So, I held a celebration party with friends.","id":"Saya lulus ujian. Jadi, saya mengadakan pesta perayaan bersama teman-teman."}]},{"pattern":"文A。それに 文B (Bun A. Soreni Bun B)","meaning":"Express 'in addition to; besides,' used to include additional information.","meaningId":"Ekspresikan 'selain; selain itu,' digunakan untuk memasukkan informasi tambahan.","formation":"Sentence A + それに + Sentence B","formationId":"Kalimat A + それに + Kalimat B","examples":[{"jp":"彼は頭がいい。それに、スポーツも得意だ。","romaji":"Kare wa atama ga ii. Soreni, supo-tsu mo tokui da.","en":"He is smart. In addition, he is good at sports.","id":"Dia pintar. Selain itu, dia pandai olahraga."},{"jp":"このケーキはおいしい。それに、値段も安い。","romaji":"Kono keeki wa oishii. Soreni, nedan mo yasui.","en":"This cake is delicious. Besides, the price is also cheap.","id":"Kue ini enak. Selain itu harganya juga murah."},{"jp":"私は日本語が話せます。それに、韓国語も話せます。","romaji":"Watashi wa nihongo ga hanasemasu. Soreni, kankokugo mo hanasemasu.","en":"I can speak Japanese. On top of that, I can also speak Korean.","id":"Saya bisa berbicara bahasa Jepang. Selain itu, saya juga bisa berbicara bahasa Korea."},{"jp":"彼女は美人だ。それに、性格もいい。","romaji":"Kanojo wa bijin da. Soreni, seikaku mo ii.","en":"She is beautiful. In addition, she has a good personality.","id":"Dia cantik. Selain itu, dia mempunyai kepribadian yang baik."}]},{"pattern":"文A。だから 文B (Bun A. Dakara Bun B)","meaning":"Express reason or cause; 'because', 'so', 'therefore'.","meaningId":"Mengungkapkan alasan atau sebab; 'karena', 'jadi', 'oleh karena itu'.","formation":"Sentence A + だから + Sentence B","formationId":"Kalimat A + だから + Kalimat B","examples":[{"jp":"明日は試験だ。だから今日勉強しなければならない。","romaji":"Ashita wa shiken da. Dakara kyou benkyou shinakereba naranai.","en":"Tomorrow is the exam, so I have to study today.","id":"Besok adalah ujian, jadi saya harus belajar hari ini."},{"jp":"この料理は簡単だ。だから初心者でも作れる。","romaji":"Kono ryouri wa kantan da. Dakara shoshinsha demo tsukureru.","en":"This dish is simple, so even beginners can make it.","id":"Hidangan ini sederhana, sehingga pemula pun bisa membuatnya."},{"jp":"彼は病気だ。だから今日学校を休む。","romaji":"Kare wa byouki da. Dakara kyou gakkou wo yasumu.","en":"He is sick, so he will take a day off from school today.","id":"Dia sakit, jadi dia akan mengambil cuti dari sekolah hari ini."},{"jp":"駅まで遠い。だからタクシーで行ったほうがいい。","romaji":"Eki made tooi. Dakara takushii de itta hou ga ii.","en":"The station is far, so it's better to go by taxi.","id":"Stasiunnya jauh, jadi lebih baik naik taksi."}]}]
